// ---------- helpers ----------
const money = (n) => {
  const v = Number(n) || 0;
  const dec = Number.isInteger(v) ? 0 : 2;
  return "$" + v.toLocaleString("es-MX", { minimumFractionDigits: dec, maximumFractionDigits: 2 });
};
const catColor = (cat) => (CATS[cat] ? CATS[cat].c : "#F04E97");
const comisionTarjeta = (o) => (o.pago === "Tarjeta de crédito" ? Math.round(((o.total || 0) + (o.envio || 0)) * 0.035) : 0);
const grandTotal = (o) => (o.total || 0) + (o.envio || 0) + comisionTarjeta(o) - (o.descuento || 0); // productos + envío + comisión − descuento
const catSoft = (cat) => (CATS[cat] ? CATS[cat].soft : "#FBD8E5");

async function loadKey(key, fallback) {
  try {
    const r = await window.storage.get(key);
    return r ? JSON.parse(r.value) : fallback;
  } catch (e) {
    return fallback;
  }
}
async function saveKey(key, val) {
  try { await window.storage.set(key, JSON.stringify(val)); }
  catch (e) { console.error("No se pudo guardar", key, e); }
}

// ---------- Lista de clientes conocidos (de pedidos + registrados) ----------
function listaClientes(orders, manuales, extra) {
  const map = {};
  (orders || []).forEach((o) => { // los pedidos vienen del más nuevo al más viejo → gana el dato más reciente
    const key = o.cliente.telefono || o.cliente.correo || o.cliente.nombre;
    if (!map[key]) map[key] = { ...o.cliente };
  });
  (manuales || []).forEach((c) => {
    const key = c.telefono || c.correo || c.nombre;
    if (!map[key]) map[key] = { ...c };
  });
  (extra || []).forEach((c) => {
    const key = c.telefono || c.correo || c.nombre;
    if (key && !map[key]) map[key] = { ...c };
  });
  return Object.values(map);
}

// Código secuencial provisional: 111,222,...,999,1111,2222,...
function codigoSecuencial(n) {
  const bloque = Math.floor(n / 9);
  const digito = (n % 9) + 1;
  return String(digito).repeat(bloque + 3);
}

// ============================================================
export default function App() {
  const [ready, setReady] = useState(false);
  const [view, setView] = useState("tienda"); // tienda | panel
  const [distsRemote, setDistsRemote] = useState({}); // distribuidoras provisionales (Supabase)
  const [tab, setTab] = useState("resumen");

  const catalog = SEED_CATALOG;
  const [stock, setStock] = useState({});
  const [orders, setOrders] = useState([]);
  const [distribs, setDistribs] = useState([]);
  const [manuales, setManuales] = useState([]);
  const [proveedorPedidos, setProveedorPedidos] = useState([]);
  const [fechaCorte, setFechaCorte] = useState("2026-09-01");

  const [cart, setCart] = useState({}); // sku -> qty
  const [panelUnlocked, setPanelUnlocked] = useState(() => { try { return localStorage.getItem("admin_ok") === "1"; } catch (e) { return false; } });
  const cerrarSesionAdmin = () => { try { localStorage.removeItem("admin_ok"); } catch (e) {} setPanelUnlocked(false); };
  const fileRef = useRef(null);
  const [promo, setPromo] = useState("");
  const [esDist, setEsDist] = useState(false);
  const [distNum, setDistNum] = useState("");
  const [filter, setFilter] = useState("Todos");
  const [modoTienda, setModoTienda] = useState("bolsas"); // bolsas | kilo
  const [cartOpen, setCartOpen] = useState(false);
  const [checkout, setCheckout] = useState(false);
  const [toast, setToast] = useState(null);

  // ---- carga inicial ----
  useEffect(() => {
    (async () => {
      const initStock = {};
      SEED_CATALOG.forEach((p) => { initStock[p.sku] = 15; });
      const st = await loadKey("inventario", initStock);
      if (!(st["JIC-CE"] > 0)) st["JIC-CE"] = 15; // Crema y Especias reactivado con 15
      const ords = await loadKey("pedidos", []);
      const dis = await loadKey("distribuidores", []);
      const man = await loadKey("clientes_manuales", []);
      const prov = await loadKey("proveedor_pedidos", []);
      const fc = await loadKey("fecha_corte", "2026-09-01");
      setStock(st);
      setOrders(ords);
      setDistribs(dis);
      setManuales(man);
      setProveedorPedidos(prov);
      setFechaCorte(fc);
      setReady(true);
    })();
  }, []);

  useEffect(() => { if (ready) saveKey("inventario", stock); }, [stock, ready]);
  useEffect(() => { if (ready) saveKey("pedidos", orders); }, [orders, ready]);
  useEffect(() => { if (ready) saveKey("distribuidores", distribs); }, [distribs, ready]);
  useEffect(() => { if (ready) saveKey("clientes_manuales", manuales); }, [manuales, ready]);
  useEffect(() => { if (ready) saveKey("proveedor_pedidos", proveedorPedidos); }, [proveedorPedidos, ready]);
  useEffect(() => { if (ready) saveKey("fecha_corte", fechaCorte); }, [fechaCorte, ready]);

  useEffect(() => {
    if (!supabase) return;
    supabase.from("distribuidoras").select("codigo,nombre,costo_base").then(({ data }) => {
      if (!data) return;
      const m = {}; data.forEach((d) => { m[d.codigo] = { nombre: d.nombre, base: Number(d.costo_base) }; });
      setDistsRemote(m);
    });
  }, []);

  // Trae TODOS los pedidos de la nube y se mantiene al dia en tiempo real
  const cargarPedidosNube = async () => {
    if (!supabase) return;
    const { data } = await supabase.from("pedidos").select("data").order("actualizado", { ascending: false });
    if (data) setOrders(data.map((r) => r.data));
  };
  useEffect(() => {
    if (!supabase) return;
    cargarPedidosNube();
    const ch = supabase.channel("pedidos_admin")
      .on("postgres_changes", { event: "*", schema: "public", table: "pedidos" }, cargarPedidosNube)
      .subscribe();
    return () => supabase.removeChannel(ch);
  }, []);

  const showToast = (msg) => { setToast(msg); setTimeout(() => setToast(null), 2600); };

  // ---- respaldo: exportar / importar ----
  const exportarRespaldo = () => {
    const data = {
      app: "Papitas Saludables", version: 1, fecha: new Date().toISOString(),
      inventario: stock, pedidos: orders, distribuidores: distribs, clientes_manuales: manuales,
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `papitas-respaldo-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast("Respaldo descargado 💾");
  };
  const importarRespaldo = (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const data = JSON.parse(reader.result);
        if (!window.confirm("Esto reemplazará los datos actuales del Panel con los del respaldo. ¿Continuar?")) { e.target.value = ""; return; }
        if (data.inventario) setStock(data.inventario);
        if (data.pedidos) setOrders(data.pedidos);
        if (data.distribuidores) setDistribs(data.distribuidores);
        if (data.clientes_manuales) setManuales(data.clientes_manuales);
        showToast("Respaldo importado ✅");
      } catch (err) {
        showToast("Archivo no válido");
      }
      e.target.value = "";
    };
    reader.readAsText(file);
  };

  // ---- carrito: bolsas (por pieza) + granel (por peso) ----
  const cartCount = Object.entries(cart).filter(([k]) => !k.includes("#")).reduce((a, [, q]) => a + q, 0); // solo bolsas
  const volTier = [...VOLUMEN].reverse().find((v) => cartCount >= v.min);
  const volUnit = volTier ? volTier.precio : 50;
  const codeKey = promo.trim().toLowerCase();
  const codigoPrecio = CODIGOS_DESCUENTO[codeKey];        // precio del código (undefined si no existe)
  const promoOk = codigoPrecio != null;
  const distKey = distNum.trim().toUpperCase().replace(/\s+/g, "");
  const DIST_MAP = { ...DISTRIBUIDORAS, ...distsRemote };
  const distConfig = esDist && DIST_MAP[distKey] ? DIST_MAP[distKey] : null;
  const distOk = !!distConfig;
  const distNombre = distConfig ? distConfig.nombre : "";

  // precio único de bolsa (cuando NO es distribuidora): público / volumen / código / cortesía
  let unitBase = volUnit;
  if (promoOk) unitBase = Math.min(unitBase, codigoPrecio);

  const precioDe = (p) => {
    if (distConfig) return precioDistribuidora(distConfig, p);
    return unitBase;
  };

  let nivelLabel = volTier ? `Mayoreo ${volTier.min}+ pzas` : "Precio público";
  if (promoOk && codigoPrecio <= volUnit) nivelLabel = "Código " + codeKey.toUpperCase();
  if (distOk) nivelLabel = `Distribuidora: ${distNombre}`;

  const unit = distOk ? null : unitBase;
  const nextVol = VOLUMEN.find((v) => v.min > cartCount);
  const kilosCount = Object.entries(cart).filter(([k]) => k.endsWith("#1000")).reduce((a, [, q]) => a + q, 0);
  const precioKilo = precioPorKilo(kilosCount);
  // precio de una presentación a granel: si la distribuidora tiene tabla, la usa; si no, precio normal
  const precioGranelDe = (p, peso, g) => {
    const cfg = distConfig && distConfig.granel && distConfig.granel[peso];
    if (cfg) return (cfg.porCategoria && cfg.porCategoria[p.categoria] != null) ? cfg.porCategoria[p.categoria] : cfg.base;
    return g.tiered ? precioKilo : g.precio;
  };
  const cartItems = Object.entries(cart)
    .filter(([, q]) => q > 0)
    .map(([key, qty]) => {
      if (key.includes("#")) { // granel: "SKU#peso"
        const [sku, peso] = key.split("#");
        const p = catalog.find((x) => x.sku === sku);
        const g = granelInfo(peso);
        if (!p || !g) return null;
        const precioG = precioGranelDe(p, peso, g);
        return { key, sku, sabor: p.sabor, categoria: p.categoria, gramaje: g.label, qty, precio: precioG, importe: precioG * qty, granel: true };
      }
      const p = catalog.find((x) => x.sku === key);
      if (!p) return null;
      const precio = precioDe(p);
      return { ...p, key, qty, precio, importe: precio * qty, granel: false };
    })
    .filter(Boolean);
  const cartTotal = cartItems.reduce((a, i) => a + i.importe, 0);
  const bagTotal = cartItems.filter((i) => !i.granel).reduce((a, i) => a + i.importe, 0);
  const cartAhorro = 50 * cartCount - bagTotal;

  const addToCart = (sku) => {
    setCart((c) => ({ ...c, [sku]: (c[sku] || 0) + 1 }));
    showToast("Agregado a tu pedido");
  };
  const setQty = (sku, qty) =>
    setCart((c) => { const n = { ...c }; if (qty <= 0) delete n[sku]; else n[sku] = qty; return n; });

  // ---- comprometido (pedidos no entregados/cancelados, desde la fecha de corte) ----
  const committed = useMemo(() => {
    const m = {};
    const corte = new Date(fechaCorte);
    orders.forEach((o) => {
      if (o.estatus === "Entregado" || o.estatus === "Cancelado") return;
      if (new Date(o.fecha) < corte) return;
      o.items.forEach((it) => { if (it.granel) return; m[it.sku] = (m[it.sku] || 0) + it.qty; });
    });
    return m;
  }, [orders, fechaCorte]);

  // ---- crear pedido ----
  // ---- sincronizacion de pedidos con la nube (Supabase) ----
  const syncPedido = (order) => {
    if (!supabase || !order) return;
    supabase.from("pedidos").upsert({
      folio: order.folio,
      telefono: (order.cliente && order.cliente.telefono) || "",
      estatus: order.estatus || "Nuevo",
      pagado: !!order.pagado,
      fecha: order.fecha || null,
      data: order,
    }, { onConflict: "folio" }).then(() => {});
  };
  const borrarPedidoNube = (folio) => {
    if (!supabase) return;
    supabase.from("pedidos").delete().eq("folio", folio).then(() => {});
  };

  const placeOrder = (cliente, extras) => {
    const folio = "PED-" + Date.now().toString(36).toUpperCase().slice(-6);
    const order = {
      folio,
      fecha: new Date().toISOString(),
      cliente,
      items: cartItems.map((i) => ({ sku: i.sku, sabor: i.sabor, categoria: i.categoria, qty: i.qty, precio: i.precio, granel: i.granel, gramaje: i.gramaje })),
      total: cartTotal,
      nivel: nivelLabel,
      unit,
      estatus: "Nuevo",
      pago: extras.pago,
      notas: extras.notas || "",
      vendedora: extras.vendedora || "Compra directa",
      codigo: promoOk ? codeKey.toUpperCase() : "",
      esDistribuidora: distOk,
      distribuidora: distOk ? distNombre : "",
      distNum: distOk ? distNum.trim() : "",
      pagado: false,
      paqueteria: "",
      guia: "",
      stockDescontado: false,
    };
    setOrders((o) => [order, ...o]);
    syncPedido(order);
    if (distOk && supabase) {
      const filas = cartItems.filter((i) => !i.granel).map((i) => ({
        codigo: distKey, sku: i.sku, sabor: i.sabor, categoria: i.categoria,
        cantidad: i.qty, costo_unit: i.precio, precio_publico: 50,
      }));
      if (filas.length) supabase.from("pedidos_dist").insert(filas).then(() => {});
    }
    showToast("¡Pedido " + folio + " guardado! 🎉");
    return folio;
  };
  // Se llama al terminar (después de mostrar el botón de WhatsApp)
  const finishCheckout = () => { setCart({}); setPromo(""); setEsDist(false); setDistNum(""); setCheckout(false); setCartOpen(false); };

  // ---- registrar solicitud de distribuidor ----
  const registrarDistribuidora = async (data) => {
    if (!supabase) return null;
    for (let i = 0; i < 6; i++) {
      const { count } = await supabase.from("distribuidoras").select("*", { count: "exact", head: true });
      const codigo = codigoSecuencial((count || 0) + i);
      const { error } = await supabase.from("distribuidoras").insert({
        codigo, nombre: data.nombre, telefono: data.telefono, correo: data.correo,
        estado: data.estado, ciudad: data.ciudad, costo_base: PRECIO_PROVISIONAL,
      });
      if (!error) {
        setDistsRemote((m) => ({ ...m, [codigo]: { nombre: data.nombre, base: PRECIO_PROVISIONAL } }));
        return codigo;
      }
    }
    return null;
  };
  const addDistribuidor = (data) => {
    const folio = "DIST-" + String(distribs.length + 1).padStart(4, "0");
    const registro = { folio, fecha: new Date().toISOString(), estatus: "Nuevo", ...data };
    setDistribs((d) => [registro, ...d]);
    return folio;
  };
  const setDistEstatus = (folio, estatus) =>
    setDistribs((list) => list.map((d) => (d.folio === folio ? { ...d, estatus } : d)));
  const deleteDist = (folio) => setDistribs((list) => list.filter((d) => d.folio !== folio));

  // ---- avanzar estatus / descontar inventario al entregar ----
  const advanceStatus = (folio) => {
    setOrders((list) =>
      list.map((o) => {
        if (o.folio !== folio) return o;
        const idx = ESTATUS.indexOf(o.estatus);
        if (idx < 0 || idx >= ESTATUS.length - 1) return o;
        const next = ESTATUS[idx + 1];
        let u;
        if (next === "Entregado" && !o.stockDescontado) {
          setStock((sk) => { const n = { ...sk }; o.items.forEach((it) => { if (it.granel) return; n[it.sku] = (n[it.sku] || 0) - it.qty; }); return n; });
          u = { ...o, estatus: next, stockDescontado: true };
        } else { u = { ...o, estatus: next }; }
        syncPedido(u); return u;
      })
    );
  };
  const setStatus = (folio, estatus) => {
    setOrders((list) =>
      list.map((o) => {
        if (o.folio !== folio) return o;
        let u;
        if (estatus === "Entregado" && !o.stockDescontado) {
          setStock((sk) => { const n = { ...sk }; o.items.forEach((it) => { if (it.granel) return; n[it.sku] = (n[it.sku] || 0) - it.qty; }); return n; });
          u = { ...o, estatus, stockDescontado: true };
        } else { u = { ...o, estatus }; }
        syncPedido(u); return u;
      })
    );
  };
  const deleteOrder = (folio) => { borrarPedidoNube(folio); setOrders((l) => l.filter((o) => o.folio !== folio)); };
  const setEnvio = (folio, val) =>
    setOrders((list) => list.map((o) => { if (o.folio !== folio) return o; const u = { ...o, envio: Math.max(0, Math.round(Number(val) || 0)) }; syncPedido(u); return u; }));
  const setDescuento = (folio, val) =>
    setOrders((list) => list.map((o) => { if (o.folio !== folio) return o; const u = { ...o, descuento: Math.max(0, Math.round(Number(val) || 0)) }; syncPedido(u); return u; }));
  const recalcTotal = (items) => items.reduce((a, it) => a + it.precio * it.qty, 0);
  const editItemQty = (folio, idx, val) =>
    setOrders((list) => list.map((o) => {
      if (o.folio !== folio) return o;
      const items = o.items.map((it, i) => (i === idx ? { ...it, qty: Math.max(1, Math.round(Number(val) || 1)) } : it));
      const u = { ...o, items, total: recalcTotal(items) }; syncPedido(u); return u;
    }));
  const removeItem = (folio, idx) =>
    setOrders((list) => list.map((o) => {
      if (o.folio !== folio) return o;
      const items = o.items.filter((_, i) => i !== idx);
      const u = { ...o, items, total: recalcTotal(items) }; syncPedido(u); return u;
    }));
  const editClienteOrder = (folio, data) =>
    setOrders((list) => list.map((o) => { if (o.folio !== folio) return o; const u = { ...o, cliente: { ...o.cliente, ...data } }; syncPedido(u); return u; }));
  const togglePagado = (folio) =>
    setOrders((list) => list.map((o) => { if (o.folio !== folio) return o; const u = { ...o, pagado: !o.pagado }; syncPedido(u); return u; }));
  const setCampo = (folio, campo, val) =>
    setOrders((list) => list.map((o) => { if (o.folio !== folio) return o; const u = { ...o, [campo]: val }; syncPedido(u); return u; }));
  const updateCliente = (key, data) => {
    setOrders((list) => list.map((o) => {
      const k = o.cliente.telefono || o.cliente.correo || o.cliente.nombre;
      if (k !== key) return o; const u = { ...o, cliente: { ...o.cliente, ...data } }; syncPedido(u); return u;
    }));
    setManuales((list) => list.map((c) => ((c.telefono || c.correo || c.nombre) === key ? { ...c, ...data } : c)));
  };
  const deleteCliente = (key) => {
    setOrders((list) => {
      list.filter((o) => (o.cliente.telefono || o.cliente.correo || o.cliente.nombre) === key).forEach((o) => borrarPedidoNube(o.folio));
      return list.filter((o) => (o.cliente.telefono || o.cliente.correo || o.cliente.nombre) !== key);
    });
    setManuales((list) => list.filter((c) => (c.telefono || c.correo || c.nombre) !== key));
  };
  const addClienteManual = (data) => setManuales((l) => [{ ...data, fecha: new Date().toISOString() }, ...l]);

  // ---- pedidos a proveedor ----
  const addProveedorPedido = (data) => {
    const folio = "PROV-" + String(proveedorPedidos.length + 1).padStart(4, "0");
    setProveedorPedidos((l) => [{ folio, fecha: new Date().toISOString(), estatus: "Pendiente", ...data }, ...l]);
    showToast("Pedido a proveedor " + folio + " guardado 📦");
  };
  const recibirProveedorPedido = (folio) => {
    setProveedorPedidos((list) => list.map((o) => {
      if (o.folio !== folio || o.estatus === "Recibido") return o;
      setStock((s) => {
        const n = { ...s };
        Object.entries(o.items).forEach(([sku, q]) => { n[sku] = (n[sku] || 0) + q; });
        return n;
      });
      return { ...o, estatus: "Recibido" };
    }));
  };
  const deleteProveedorPedido = (folio) => setProveedorPedidos((l) => l.filter((o) => o.folio !== folio));

  // ---- inventario ----
  const setStockVal = (sku, val) => setStock((s) => ({ ...s, [sku]: Math.round(Number(val) || 0) }));
  const bump = (sku, d) => setStock((s) => ({ ...s, [sku]: (Number(s[sku]) || 0) + d }));

  const lowStockCount = catalog.filter((p) => p.activo && (stock[p.sku] ?? 0) < p.min).length;

  const disponibles = catalog.filter((p) => p.activo);
  const filtered = filter === "Todos" ? disponibles : disponibles.filter((p) => p.categoria === filter);

  if (!ready) {
    return (
      <div style={{ ...styles.page, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <style>{CSS}</style>
        <div className="pulse" style={{ fontFamily: "'Baloo 2', cursive", color: "#F04E97", fontSize: 28 }}>
          Preparando tus papitas…
        </div>
      </div>
    );
  }

  return (
    <div style={styles.page}>
      <style>{CSS}</style>

      {/* ---------- HEADER ---------- */}
      <header style={styles.header}>
        <div style={styles.brandWrap}>
          <img src={LOGO} alt="Papitas Saludables" style={styles.logo} />
        </div>

        <nav style={styles.nav}>
          <button
            className="tabbtn"
            style={view === "tienda" ? styles.navActive : styles.navIdle}
            onClick={() => setView("tienda")}
          >
            🛒 Tienda
          </button>
          <button
            className="tabbtn"
            style={view === "rastrear" ? styles.navActive : styles.navIdle}
            onClick={() => setView("rastrear")}
          >
            📦 Rastrea tu pedido
          </button>
          <button
            className="tabbtn"
            style={view === "boletin" ? styles.navActive : styles.navIdle}
            onClick={() => setView("boletin")}
          >
            📰 Boletín
          </button>
          <button
            className="tabbtn"
            style={view === "mipanel" ? styles.navDist : styles.navIdle}
            onClick={() => setView("mipanel")}
          >
            📈 Mi tablero
          </button>
          <button
            className="tabbtn"
            style={view === "distribuidor" ? styles.navDist : styles.navIdle}
            onClick={() => setView("distribuidor")}
          >
            🤝 Quiero ser distribuidor
          </button>
          <button
            className="tabbtn"
            style={view === "panel" ? styles.navActive : styles.navIdle}
            onClick={() => setView("panel")}
          >
            📊 Panel
          </button>
          {view === "tienda" && (
            <button className="cartbtn" onClick={() => setCartOpen(true)} aria-label="Ver pedido">
              🛍️
              {cartCount > 0 && <span className="cartbadge">{cartCount}</span>}
            </button>
          )}
        </nav>
      </header>

      {/* ---------- TIENDA ---------- */}
      {view === "tienda" && (
        <main style={styles.main}>
          <section style={styles.hero} className="fadeup">
            <h1 style={styles.heroTitle}>Botana deshidratada, hecha con cariño</h1>
            <p style={styles.heroSub}>
              {disponibles.length} sabores en presentación individual. Elige los tuyos, llena tus datos y
              nosotros nos encargamos del resto.
            </p>
            <div style={styles.promoBar}>
              <span className="promo-pill">100% vegetal</span>
              <span className="promo-pill">Verduras naturales</span>
              <span className="promo-pill">Hechas con amor</span>
            </div>
          </section>

          {/* interruptor bolsas / por kilo */}
          <div style={styles.modoRow}>
            <button
              className="tabbtn"
              style={modoTienda === "bolsas" ? styles.navActive : styles.navIdle}
              onClick={() => setModoTienda("bolsas")}
            >
              🛍️ Bolsas
            </button>
            <button
              className="tabbtn"
              style={modoTienda === "kilo" ? styles.navActive : styles.navIdle}
              onClick={() => setModoTienda("kilo")}
            >
              ⚖️ Por kilo
            </button>
          </div>

          {/* filtros por categoría */}
          <div style={styles.chips}>
            <Chip active={filter === "Todos"} color="#F04E97" onClick={() => setFilter("Todos")}>
              Todos
            </Chip>
            {CAT_ORDER.map((cat) => (
              <Chip key={cat} active={filter === cat} color={catColor(cat)} onClick={() => setFilter(cat)}>
                {cat}
              </Chip>
            ))}
          </div>

          {/* grid de productos */}
          {modoTienda === "bolsas" ? (
            <div style={styles.grid}>
              {filtered.map((p) => (
                <ProductCard key={p.sku} p={p} inCart={cart[p.sku] || 0} onAdd={() => addToCart(p.sku)} />
              ))}
            </div>
          ) : (
            <>
              <p style={{ textAlign: "center", color: "#7a6570", margin: "0 0 16px" }}>
                Elige tu sabor y presentación: 250g $100 · 500g $195 · 1kg $380 (2+ kg $370 · 5+ kg $350).
              </p>
              <div style={styles.grid}>
                {filtered.map((p) => (
                  <GranelCard key={p.sku} p={p} cart={cart} precioGranelDe={precioGranelDe} onAdd={(peso) => addToCart(`${p.sku}#${peso}`)} />
                ))}
              </div>
            </>
          )}
        </main>
      )}

      {/* ---------- RASTREA TU PEDIDO ---------- */}
      {view === "rastrear" && (
        <main style={styles.main}>
          <RastrearView orders={orders} />
        </main>
      )}

      {/* ---------- BOLETÍN ---------- */}
      {view === "boletin" && (
        <main style={styles.main}>
          <Boletin />
        </main>
      )}

      {/* ---------- MI PANEL (distribuidora) ---------- */}
      {view === "mipanel" && (
        <main style={styles.main}>
          <MiPanel />
        </main>
      )}

      {/* ---------- QUIERO SER DISTRIBUIDOR ---------- */}
      {view === "distribuidor" && (
        <main style={styles.main}>
          <DistribuidorView onSubmit={addDistribuidor} onRegistrar={registrarDistribuidora} onGoTienda={() => setView("tienda")} />
        </main>
      )}

      {/* ---------- PANEL ---------- */}
      {view === "panel" && !panelUnlocked && (
        <main style={styles.main}>
          <PinGate onOk={() => setPanelUnlocked(true)} />
        </main>
      )}

      {view === "panel" && panelUnlocked && (
        <main style={styles.main}>
          <div style={styles.panelToolbar}>
            <button className="ghost small" onClick={exportarRespaldo}>⬇️ Exportar respaldo</button>
            <button className="ghost small" onClick={() => fileRef.current && fileRef.current.click()}>⬆️ Importar respaldo</button>
            <input ref={fileRef} type="file" accept=".json,application/json" onChange={importarRespaldo} style={{ display: "none" }} />
            <button className="ghost small" onClick={cerrarSesionAdmin}>🔒 Cerrar sesión</button>
          </div>

          <div style={styles.panelTabs}>
            {[
              ["resumen", "Resumen"],
              ["pedidos", "Pedidos" + (orders.filter((o) => o.estatus === "Nuevo").length ? ` (${orders.filter((o) => o.estatus === "Nuevo").length})` : "")],
              ["inventario", "Inventario" + (lowStockCount ? ` ⚠️${lowStockCount}` : "")],
              ["proveedor", "Proveedor"],
              ["clientes", "Clientes"],
              ["vendedoras", "Vendedoras"],
              ["distribuidores", "Distribuidores" + (distribs.filter((d) => d.estatus === "Nuevo").length ? ` (${distribs.filter((d) => d.estatus === "Nuevo").length})` : "")],
            ].map(([id, label]) => (
              <button
                key={id}
                className="tabbtn"
                style={tab === id ? styles.ptabActive : styles.ptabIdle}
                onClick={() => setTab(id)}
              >
                {label}
              </button>
            ))}
          </div>

          {tab === "resumen" && (
            <Resumen orders={orders} catalog={catalog} stock={stock} committed={committed} proveedorPedidos={proveedorPedidos} fechaCorte={fechaCorte} setFechaCorte={setFechaCorte} />
          )}
          {tab === "pedidos" && (
            <Pedidos orders={orders} onAdvance={advanceStatus} onSet={setStatus} onDelete={deleteOrder} onEnvio={setEnvio} onPagado={togglePagado} onCampo={setCampo} onDescuento={setDescuento} onEditItem={editItemQty} onRemoveItem={removeItem} onEditCliente={editClienteOrder} />
          )}
          {tab === "inventario" && (
            <Inventario
              catalog={catalog}
              stock={stock}
              committed={committed}
              onSet={setStockVal}
              onBump={bump}
            />
          )}
          {tab === "clientes" && <Clientes orders={orders} manuales={manuales} onUpdate={updateCliente} onDelete={deleteCliente} onAdd={addClienteManual} />}
          {tab === "proveedor" && (
            <Proveedores catalog={catalog} stock={stock} committed={committed} pedidos={proveedorPedidos}
              onAdd={addProveedorPedido} onRecibir={recibirProveedorPedido} onDelete={deleteProveedorPedido} />
          )}
          {tab === "vendedoras" && <Vendedoras orders={orders} />}
          {tab === "distribuidores" && (
            <Distribuidores distribs={distribs} onSet={setDistEstatus} onDelete={deleteDist} />
          )}
        </main>
      )}

      {/* ---------- CARRITO ---------- */}
      {cartOpen && (
        <>
          <div style={styles.backdrop} onClick={() => setCartOpen(false)} />
          <aside style={styles.drawer} className="slidein">
            <div style={styles.drawerHead}>
              <h2 style={styles.drawerTitle}>Tu pedido</h2>
              <button className="closex" onClick={() => setCartOpen(false)}>✕</button>
            </div>

            {cartItems.length === 0 ? (
              <div style={styles.empty}>
                <div style={{ fontSize: 44 }}>🥕</div>
                <p style={{ margin: "10px 0 4px", fontWeight: 800 }}>Aún no eliges nada</p>
                <p style={{ color: "#8a7683", fontSize: 14 }}>Agrega tus sabores favoritos desde la tienda.</p>
              </div>
            ) : (
              <>
                <div style={{ flex: 1, overflowY: "auto", padding: "4px 4px 0" }}>
                  {cartItems.map((i) => (
                    <div key={i.key} style={styles.cartRow}>
                      <span style={{ ...styles.dot, background: catColor(i.categoria) }} />
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={styles.cartName}>{i.sabor}</div>
                        <div style={styles.cartMeta}>{i.categoria} · {i.gramaje}{(distOk || i.granel) ? ` · ${money(i.precio)} c/u` : ""}</div>
                      </div>
                      <div style={styles.stepper}>
                        <button className="stepbtn" onClick={() => setQty(i.key, i.qty - 1)}>−</button>
                        <span style={styles.qty}>{i.qty}</span>
                        <button className="stepbtn" onClick={() => setQty(i.key, i.qty + 1)}>+</button>
                      </div>
                      <div style={styles.cartPrice}>{money(i.importe)}</div>
                    </div>
                  ))}
                </div>
                <div style={styles.drawerFoot}>
                  <div style={styles.promoRow}>
                    <input
                      style={{ ...inp(), border: `2px solid ${promoOk ? "#9FC131" : "#efe2d6"}`, flex: 1 }}
                      placeholder="Código de descuento"
                      value={promo}
                      onChange={(e) => setPromo(e.target.value)}
                    />
                    {promoOk && <span style={{ color: "#6e8f18", fontWeight: 800, whiteSpace: "nowrap" }}>✓ aplicado</span>}
                  </div>
                  {promo.trim() && !promoOk && (
                    <div style={{ fontSize: 12, color: "#D63384", fontWeight: 700, margin: "-4px 2px 8px" }}>
                      Código no válido
                    </div>
                  )}
                  <div style={styles.distToggle}>
                    <label style={{ display: "flex", alignItems: "center", gap: 8, cursor: "pointer", fontWeight: 800, fontSize: 14 }}>
                      <input type="checkbox" checked={esDist} onChange={(e) => setEsDist(e.target.checked)} style={{ width: 18, height: 18 }} />
                      🏷️ Soy distribuidora (precio especial)
                    </label>
                    {esDist && (
                      <div style={{ marginTop: 8 }}>
                        <input
                          style={{ ...inp(), border: `2px solid ${distOk ? "#9FC131" : "#E9E2F4"}`, width: "100%" }}
                          placeholder="Número o código de distribuidora"
                          value={distNum}
                          onChange={(e) => setDistNum(e.target.value)}
                        />
                        {distOk && (
                          <div style={{ fontSize: 13, color: "#6e8f18", fontWeight: 800, marginTop: 6 }}>
                            ✓ Precio de distribuidora aplicado · {distNombre}
                          </div>
                        )}
                        {distNum.trim() && !distOk && (
                          <div style={{ fontSize: 12, color: "#D63384", fontWeight: 700, marginTop: 6 }}>
                            Número no reconocido
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                  <div style={styles.tierBox}>
                    <div style={styles.tierTop}>
                      <span className="tierbadge" style={{ background: distOk ? "#9B6FCE" : (volTier || promoOk) ? "#9FC131" : "#F2A93B" }}>
                        {nivelLabel}
                      </span>
                      <span style={{ fontFamily: "'Baloo 2', cursive", fontSize: 18, color: "#4A2C3A" }}>
                        {unit != null
                          ? <>{money(unit)} <span style={{ fontSize: 12, color: "#8a7683", fontFamily: "'Nunito',sans-serif" }}>c/u</span></>
                          : <span style={{ fontSize: 13, color: "#8a7683", fontFamily: "'Nunito',sans-serif" }}>precio por producto</span>}
                      </span>
                    </div>
                    {cartAhorro > 0 && (
                      <div style={styles.tierSave}>Descuento aplicado · ahorras {money(cartAhorro)} 🎉</div>
                    )}
                    {!distOk && nextVol && (
                      <div style={styles.tierNudge}>
                        Agrega <b>{nextVol.min - cartCount}</b> pieza(s) más y baja a <b>{money(nextVol.precio)}</b> c/u
                      </div>
                    )}
                  </div>
                  <div style={styles.totalRow}>
                    <span>Total · {cartCount} pza</span>
                    <span style={{ fontFamily: "'Baloo 2', cursive", fontSize: 24, color: "#F04E97" }}>
                      {money(cartTotal)}
                    </span>
                  </div>
                  <button className="cta" style={{ width: "100%" }} onClick={() => setCheckout(true)}>
                    Continuar con mis datos →
                  </button>
                </div>
              </>
            )}
          </aside>
        </>
      )}

      {/* ---------- CHECKOUT ---------- */}
      {checkout && (
        <Checkout
          total={cartTotal}
          items={cartItems}
          count={cartCount}
          unit={unit}
          nivel={nivelLabel}
          ahorro={cartAhorro}
          codigo={promoOk ? codeKey.toUpperCase() : ""}
          distribuidora={distOk ? `${distNombre} (núm. ${distNum.trim()})` : ""}
          prefill={distOk ? { nombre: distNombre, ...(distConfig.datos || {}) } : null}
          clientes={listaClientes(orders, manuales, CLIENTES)}
          onClose={() => setCheckout(false)}
          onFinish={finishCheckout}
          onSubmit={placeOrder}
        />
      )}

      {toast && <div className="toast">{toast}</div>}

      <footer style={styles.footer}>
        Papitas Saludables · Tus datos se guardan de forma segura en este dispositivo.
      </footer>
    </div>
  );
}

/* ============================================================
   COMPONENTES
   ============================================================ */

function Chip({ active, color, onClick, children }) {
  return (
    <button
      className="chip"
      onClick={onClick}
      style={{
        background: active ? color : "#fff",
        color: active ? "#fff" : "#5a4450",
        borderColor: active ? color : "#f0e3d8",
        boxShadow: active ? `0 4px 0 ${shade(color)}` : "0 3px 0 #efe2d6",
      }}
    >
      {children}
    </button>
  );
}

function ProductCard({ p, inCart, onAdd }) {
  const c = catColor(p.categoria);
  const photo = PHOTOS[p.sku];
  return (
    <div className="card fadeup" style={styles.card}>
      <div style={{ ...styles.cardTop, height: photo ? 170 : 84, padding: 0, background: photo ? "#fff" : catSoft(p.categoria) }}>
        {photo ? (
          <>
            <img src={photo} alt={p.sabor} style={styles.cardImg} />
            <span className="grampill">{p.gramaje}</span>
          </>
        ) : (
          <div className="bag" style={{ background: c }}>
            <span style={{ fontFamily: "'Baloo 2', cursive", fontSize: 13, color: "#fff", lineHeight: 1 }}>
              {p.gramaje}
            </span>
          </div>
        )}
        <span className="catbadge" style={{ background: c }}>{p.categoria}</span>
      </div>
      <div style={{ padding: "12px 14px 14px" }}>
        <h3 style={styles.cardName}>{p.sabor}</h3>
        <div style={styles.cardRow}>
          <div>
            <div style={styles.price}>{money(p.precios.pub)}</div>
          </div>
          <button className="addbtn" style={{ background: c, boxShadow: `0 4px 0 ${shade(c)}` }} onClick={onAdd}>
            {inCart > 0 ? `Agregar · ${inCart}` : "Agregar"}
          </button>
        </div>
      </div>
    </div>
  );
}

function GranelCard({ p, cart, precioGranelDe, onAdd }) {
  const c = catColor(p.categoria);
  const photo = PHOTOS[p.sku];
  return (
    <div className="card fadeup" style={styles.card}>
      <div style={{ ...styles.cardTop, height: photo ? 130 : 70, padding: 0, background: photo ? "#fff" : catSoft(p.categoria) }}>
        {photo ? <img src={photo} alt={p.sabor} style={styles.cardImg} /> : (
          <div className="bag" style={{ background: c }}>
            <span style={{ fontFamily: "'Baloo 2', cursive", fontSize: 13, color: "#fff" }}>granel</span>
          </div>
        )}
        <span className="catbadge" style={{ background: c }}>{p.categoria}</span>
      </div>
      <div style={{ padding: "12px 14px 14px" }}>
        <h3 style={styles.cardName}>{p.sabor}</h3>
        <div style={{ display: "flex", flexDirection: "column", gap: 6, marginTop: 8 }}>
          {GRANEL.map((g) => {
            const cnt = cart[`${p.sku}#${g.peso}`] || 0;
            const precio = precioGranelDe(p, g.peso, g);
            return (
              <button
                key={g.peso}
                className="granelbtn"
                style={{ borderColor: c }}
                onClick={() => onAdd(g.peso)}
              >
                <span style={{ fontWeight: 800 }}>{g.label}</span>
                <span style={{ display: "flex", alignItems: "center", gap: 6 }}>
                  <span style={{ fontFamily: "'Baloo 2', cursive", color: "#F04E97" }}>{money(precio)}</span>
                  <span className="granelplus" style={{ background: c }}>{cnt > 0 ? cnt : "+"}</span>
                </span>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function Checkout({ total, items, count, unit, nivel, ahorro, codigo, distribuidora, prefill, clientes, onClose, onFinish, onSubmit }) {
  const [f, setF] = useState({
    nombre: prefill?.nombre || "", telefono: prefill?.telefono || "", correo: prefill?.correo || "",
    calle: prefill?.calle || "", colonia: prefill?.colonia || "", cp: prefill?.cp || "",
    estado: prefill?.estado || "", referencias: prefill?.referencias || "", pago: "Efectivo", notas: "",
    vendedora: (prefill?.nombre && VENDEDORAS.includes(prefill.nombre)) ? prefill.nombre : "", vendedoraOtra: "",
  });
  const [busqueda, setBusqueda] = useState("");
  const matches = useMemo(() => {
    const t = busqueda.trim().toLowerCase();
    if (t.length < 2) return [];
    return (clientes || []).filter((c) => (c.nombre + " " + (c.telefono || "")).toLowerCase().includes(t)).slice(0, 6);
  }, [busqueda, clientes]);
  const usarCliente = (c) => {
    setF((prev) => ({
      ...prev,
      nombre: c.nombre || "", telefono: c.telefono || "", correo: c.correo || "",
      calle: c.calle || "", colonia: c.colonia || "", cp: c.cp || "",
      estado: c.estado || "", referencias: c.referencias || "",
    }));
    setBusqueda("");
    setErr({});
  };
  const [err, setErr] = useState({});
  const [done, setDone] = useState(null); // { folio, waUrl }
  const set = (k) => (e) => setF({ ...f, [k]: e.target.value });
  const comision = f.pago === "Tarjeta de crédito" ? Math.round(total * 0.035) : 0;
  const totalFinal = total + comision;

  const validate = () => {
    const e = {};
    if (!f.nombre.trim()) e.nombre = "Escribe el nombre completo";
    if (!/^\d{10}$/.test(f.telefono.replace(/\D/g, "")) ) e.telefono = "10 dígitos";
    if (f.correo && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(f.correo)) e.correo = "Correo no válido";
    if (!f.calle.trim()) e.calle = "Falta la calle y número";
    if (!f.colonia.trim()) e.colonia = "Falta la colonia";
    if (!/^\d{5}$/.test(f.cp)) e.cp = "5 dígitos";
    if (!f.estado) e.estado = "Elige un estado";
    if (!f.vendedora) e.vendedora = "Indica quién te la ofreció";
    if (f.vendedora === "__otra__" && !f.vendedoraOtra.trim()) e.vendedoraOtra = "Escribe el nombre";
    setErr(e);
    return Object.keys(e).length === 0;
  };

  const submit = () => {
    if (!validate()) return;
    const vend = f.vendedora === "__otra__" ? f.vendedoraOtra.trim() : f.vendedora;
    const folio = onSubmit(
      {
        nombre: f.nombre.trim(), telefono: f.telefono.trim(), correo: f.correo.trim(),
        calle: f.calle.trim(), colonia: f.colonia.trim(), cp: f.cp.trim(),
        estado: f.estado, referencias: f.referencias.trim(),
      },
      { pago: f.pago, notas: f.notas.trim(), vendedora: vend }
    );
    // Armar el mensaje de WhatsApp con todos los datos del pedido
    const lineas = items.map((i) => `• ${i.qty} x ${i.sabor} (${i.categoria}) — ${money(i.importe)}`).join("\n");
    const msg =
      `🥔 *Nuevo pedido — Papitas Saludables*\n` +
      `Folio: ${folio}\n\n` +
      `*Cliente:* ${f.nombre.trim()}\n` +
      `*Tel:* ${f.telefono.trim()}\n` +
      (f.correo.trim() ? `*Correo:* ${f.correo.trim()}\n` : "") +
      `*Dirección:* ${f.calle.trim()}, Col. ${f.colonia.trim()}, C.P. ${f.cp.trim()}, ${f.estado}\n` +
      (f.referencias.trim() ? `*Referencias:* ${f.referencias.trim()}\n` : "") +
      `*Vendedora:* ${vend}\n` +
      (distribuidora ? `*Distribuidora:* ${distribuidora}\n` : "") +
      `\n*Productos:*\n${lineas}\n\n` +
      `*Piezas:* ${count}\n` +
      `*Precio:* ${nivel}${unit != null ? ` — ${money(unit)} c/u` : " (precio por producto)"}\n` +
      (codigo ? `*Código:* ${codigo}\n` : "") +
      (comision > 0 ? `*Comisión tarjeta (3.5%):* ${money(comision)}\n` : "") +
      `*Total:* ${money(totalFinal)}\n` +
      `*Pago:* ${f.pago}` +
      (f.notas.trim() ? `\n*Notas:* ${f.notas.trim()}` : "");
    const waUrl = `https://wa.me/${WHATSAPP_TIENDA}?text=${encodeURIComponent(msg)}`;
    setDone({ folio, waUrl });
  };

  // ----- pantalla de éxito con botón de WhatsApp -----
  if (done) {
    return (
      <>
        <div style={styles.backdrop} onClick={onFinish} />
        <div style={styles.modal} className="popin">
          <div style={{ textAlign: "center", padding: "34px 24px 28px" }}>
            <div style={{ fontSize: 56 }}>🎉</div>
            <h2 style={{ fontFamily: "'Baloo 2', cursive", fontSize: 28, color: "#F04E97", margin: "6px 0 4px" }}>
              ¡Pedido {done.folio} listo!
            </h2>
            <p style={{ color: "#7a6570", fontSize: 15, lineHeight: 1.5, maxWidth: 380, margin: "0 auto 20px" }}>
              Toca el botón para enviarnos tu pedido por WhatsApp. Así lo recibimos al instante y te
              confirmamos el envío.
            </p>
            <a className="wabtn big" href={done.waUrl} target="_blank" rel="noopener noreferrer">
              📲 Enviar mi pedido por WhatsApp
            </a>
            <div style={{ marginTop: 14 }}>
              <button className="ghost small" onClick={onFinish}>Cerrar</button>
            </div>
          </div>
        </div>
      </>
    );
  }

  return (
    <>
      <div style={styles.backdrop} onClick={onClose} />
      <div style={styles.modal} className="popin">
        <div style={styles.modalHead}>
          <h2 style={styles.drawerTitle}>Tus datos de envío</h2>
          <button className="closex" onClick={onClose}>✕</button>
        </div>

        <div style={{ padding: "0 20px 4px" }}>
          <div style={styles.orderMini}>
            {count} pza · {nivel}{unit != null ? ` · ${money(unit)} c/u` : ""} · <b style={{ color: "#F04E97" }}>{money(totalFinal)}</b>
            {ahorro > 0 && <span style={{ color: "#6e8f18", fontWeight: 800 }}> · ahorras {money(ahorro)}</span>}
          </div>
          {comision > 0 && (
            <div style={{ fontSize: 12, color: "#8a7683", marginTop: 4 }}>
              Incluye comisión por pago con tarjeta (3.5%): {money(comision)}
            </div>
          )}
        </div>

        <div style={styles.form}>
          {(clientes || []).length > 0 && (
            <div style={styles.reBox}>
              <span style={styles.flabel}>¿Ya nos compraste antes? Búscate y llenamos tus datos 💛</span>
              <input
                style={{ ...inp(), marginTop: 4 }}
                placeholder="Escribe tu nombre o teléfono"
                value={busqueda}
                onChange={(e) => setBusqueda(e.target.value)}
              />
              {matches.length > 0 && (
                <div style={styles.reList}>
                  {matches.map((c, i) => (
                    <button key={i} className="rerow" onClick={() => usarCliente(c)}>
                      <b>{c.nombre}</b> · {c.telefono}
                    </button>
                  ))}
                </div>
              )}
              {busqueda.trim().length >= 2 && matches.length === 0 && (
                <div style={{ fontSize: 12, color: "#8a7683", marginTop: 6 }}>No te encontramos. Llena tus datos abajo 👇</div>
              )}
            </div>
          )}
          <Field label="Nombre completo" err={err.nombre}>
            <input style={inp(err.nombre)} value={f.nombre} onChange={set("nombre")} placeholder="Ej. Ana López García" />
          </Field>
          <div style={styles.two}>
            <Field label="Teléfono (WhatsApp)" err={err.telefono}>
              <input style={inp(err.telefono)} value={f.telefono} onChange={set("telefono")} inputMode="numeric" placeholder="10 dígitos" />
            </Field>
            <Field label="Correo electrónico" err={err.correo}>
              <input style={inp(err.correo)} value={f.correo} onChange={set("correo")} placeholder="correo@ejemplo.com" />
            </Field>
          </div>
          <Field label="Calle y número" err={err.calle}>
            <input style={inp(err.calle)} value={f.calle} onChange={set("calle")} placeholder="Ej. Av. Hidalgo 123, Int. 4" />
          </Field>
          <div style={styles.two}>
            <Field label="Colonia" err={err.colonia}>
              <input style={inp(err.colonia)} value={f.colonia} onChange={set("colonia")} placeholder="Ej. Centro" />
            </Field>
            <Field label="Código postal" err={err.cp}>
              <input style={inp(err.cp)} value={f.cp} onChange={set("cp")} inputMode="numeric" maxLength={5} placeholder="00000" />
            </Field>
          </div>
          <Field label="Estado" err={err.estado}>
            <select style={inp(err.estado)} value={f.estado} onChange={set("estado")}>
              <option value="">Selecciona…</option>
              {ESTADOS_MX.map((e) => <option key={e} value={e}>{e}</option>)}
            </select>
          </Field>
          <Field label="Referencias (opcional)">
            <input style={inp()} value={f.referencias} onChange={set("referencias")} placeholder="Entre calles, color de casa…" />
          </Field>

          <div style={styles.vendBox}>
            <Field label="¿Quién te ofreció las papitas? *" err={err.vendedora}>
              <select style={inp(err.vendedora)} value={f.vendedora} onChange={set("vendedora")}>
                <option value="">Selecciona…</option>
                {VENDEDORAS.map((v) => <option key={v} value={v}>{v}</option>)}
                <option value="__otra__">Otra (escribir nombre)</option>
                <option value="Compra directa">Nadie / compra directa</option>
              </select>
            </Field>
            {f.vendedora === "__otra__" && (
              <div style={{ marginTop: 10 }}>
                <Field label="Nombre de tu vendedora *" err={err.vendedoraOtra}>
                  <input style={inp(err.vendedoraOtra)} value={f.vendedoraOtra} onChange={set("vendedoraOtra")} placeholder="Nombre de quien te la ofreció" />
                </Field>
              </div>
            )}
            <p style={{ fontSize: 12, color: "#8a7683", margin: "8px 2px 0" }}>
              Así respetamos a la persona que te atendió y llevamos bien tu registro. 💛
            </p>
          </div>

          <div style={styles.two}>
            <Field label="Forma de pago">
              <select style={inp()} value={f.pago} onChange={set("pago")}>
                <option>Efectivo</option>
                <option>Transferencia</option>
                <option>Depósito</option>
                <option>Tarjeta de crédito</option>
              </select>
            </Field>
            <Field label="Notas del pedido (opcional)">
              <input style={inp()} value={f.notas} onChange={set("notas")} placeholder="Ej. entregar en la tarde" />
            </Field>
          </div>
        </div>

        <div style={styles.modalFoot}>
          <button className="ghost" onClick={onClose}>Volver</button>
          <button className="cta" onClick={submit}>Confirmar y enviar por WhatsApp →</button>
        </div>
      </div>
    </>
  );
}

function Field({ label, err, children }) {
  return (
    <label style={styles.field}>
      <span style={styles.flabel}>{label}{err && <em style={styles.ferr}> · {err}</em>}</span>
      {children}
    </label>
  );
}

// ---------------- CANDADO DEL PANEL (login de administradora) ----------------
function PinGate({ onOk }) {
  const [usuario, setUsuario] = useState("");
  const [clave, setClave] = useState("");
  const [error, setError] = useState(false);
  const submit = () => {
    if (usuario.trim().toLowerCase() === ADMIN_USUARIO && clave === ADMIN_CLAVE) {
      try { localStorage.setItem("admin_ok", "1"); } catch (e) {}
      onOk();
    } else { setError(true); }
  };
  return (
    <div className="fadeup" style={{ maxWidth: 380, margin: "40px auto", textAlign: "center" }}>
      <div style={{ fontSize: 52 }}>🔒</div>
      <h1 style={{ fontFamily: "'Baloo 2', cursive", fontSize: 26, color: "#4A2C3A", margin: "8px 0 4px" }}>Panel de administradora</h1>
      <p style={{ color: "#7a6570", marginBottom: 18 }}>Inicia sesión para administrar tu tienda.</p>
      <div style={styles.pinCard}>
        <input
          value={usuario}
          onChange={(e) => { setUsuario(e.target.value); setError(false); }}
          onKeyDown={(e) => { if (e.key === "Enter") submit(); }}
          placeholder="Usuario"
          autoFocus
          autoCapitalize="none"
          style={{ ...inp(error), marginBottom: 10 }}
        />
        <input
          type="password"
          value={clave}
          onChange={(e) => { setClave(e.target.value); setError(false); }}
          onKeyDown={(e) => { if (e.key === "Enter") submit(); }}
          placeholder="Contraseña"
          style={inp(error)}
        />
        {error && <div style={{ color: "#D63384", fontWeight: 800, fontSize: 13, marginTop: 8 }}>Usuario o contraseña incorrectos</div>}
        <button className="cta" style={{ width: "100%", marginTop: 14 }} onClick={submit}>Entrar</button>
      </div>
    </div>
  );
}

// ---------------- PANEL: RESUMEN ----------------
function Resumen({ orders, catalog, stock, committed, proveedorPedidos, fechaCorte, setFechaCorte }) {
  const nuevos = orders.filter((o) => o.estatus === "Nuevo").length;
  const activos = orders.filter((o) => o.estatus !== "Entregado" && o.estatus !== "Cancelado");
  const vigentes = orders.filter((o) => o.estatus !== "Cancelado");
  const cobrado = vigentes.filter((o) => o.pagado).reduce((a, o) => a + grandTotal(o), 0);
  const porCobrar = vigentes.filter((o) => !o.pagado).reduce((a, o) => a + grandTotal(o), 0);
  const clientes = new Set(orders.map((o) => o.cliente.telefono || o.cliente.correo || o.cliente.nombre)).size;
  const bajos = catalog.filter((p) => p.activo && (stock[p.sku] ?? 0) < p.min);

  // por producir: cubrir pedidos + reponer stock mínimo, menos lo que ya hay y lo que está por llegar
  const qtyDe = (o, sku) => o.items.filter((it) => !it.granel && it.sku === sku).reduce((a, it) => a + it.qty, 0);
  const porLlegar = {};
  (proveedorPedidos || []).filter((o) => o.estatus === "Pendiente").forEach((o) => {
    Object.entries(o.items).forEach(([sku, q]) => { porLlegar[sku] = (porLlegar[sku] || 0) + q; });
  });
  const porProducir = catalog
    .filter((p) => p.activo)
    .map((p) => {
      const paraPedidos = committed[p.sku] || 0;
      const paraStock = p.min;
      const existencia = stock[p.sku] ?? 0;
      const usable = Math.max(0, existencia); // el stock negativo (entregas viejas) NO se reabastece
      const enCamino = porLlegar[p.sku] || 0;
      const pendientes = orders
        .filter((o) => o.estatus !== "Entregado" && o.estatus !== "Cancelado" && new Date(o.fecha) >= new Date(fechaCorte))
        .map((o) => ({ folio: o.folio, nombre: o.cliente.nombre, qty: qtyDe(o, p.sku) }))
        .filter((x) => x.qty > 0);
      const entregados = orders
        .filter((o) => o.estatus === "Entregado")
        .map((o) => ({ folio: o.folio, nombre: o.cliente.nombre, qty: qtyDe(o, p.sku) }))
        .filter((x) => x.qty > 0);
      return { ...p, paraPedidos, paraStock, existencia, usable, enCamino, pendientes, entregados, falta: paraPedidos + paraStock - usable - enCamino };
    })
    .filter((p) => p.falta > 0)
    .sort((a, b) => b.falta - a.falta);
  const totalSurtir = porProducir.reduce((a, p) => a + p.falta, 0);

  return (
    <div className="fadeup">
      <div style={styles.corteRow}>
        <span style={{ fontWeight: 800, fontSize: 14 }}>Contar pedidos desde:</span>
        <input type="date" value={fechaCorte} onChange={(e) => setFechaCorte(e.target.value)} style={{ ...inp(), width: "auto", padding: "8px 10px" }} />
        <span style={{ fontSize: 12, color: "#8a7683" }}>Solo estos pedidos cuentan para “surtir” y para Proveedor.</span>
      </div>
      <div style={styles.kpis}>
        <Kpi color="#F04E97" label="Pedidos nuevos" value={nuevos} />
        <Kpi color="#F2A93B" label="Pedidos activos" value={activos.length} />
        <Kpi color="#9FC131" label="Cobrado" value={money(cobrado)} />
        <Kpi color="#2FB6A0" label="Por cobrar" value={money(porCobrar)} />
        <Kpi color="#9B6FCE" label="Clientes" value={clientes} />
        <Kpi color="#E8477E" label="Sabores en stock bajo" value={bajos.length} />
      </div>

      <div style={styles.twoCol}>
        <Panel title="Por producir / surtir">
          {porProducir.length === 0 ? (
            <Empty icon="✅" text="Todo lo pedido está cubierto con tu inventario." />
          ) : (
            <>
              <div style={styles.totalSurtir}>
                Total a surtir: <b style={{ fontFamily: "'Baloo 2', cursive", fontSize: 18 }}>{totalSurtir} pza</b>
              </div>
              {porProducir.map((p) => (
              <div key={p.sku} style={styles.listRow}>
                <span style={{ ...styles.dot, background: catColor(p.categoria) }} />
                <span style={{ flex: 1, fontWeight: 700 }}>{p.sabor}</span>
                <span style={{ color: "#8a7683", fontSize: 13, marginRight: 10 }}>{p.categoria}</span>
                <span className="tip">
                  <span className="pillbad" style={{ background: "#FBD8E5", color: "#D63384" }}>
                    surtir {p.falta}
                  </span>
                  <span className="tiptext">
                    <b>A surtir: {p.falta}</b>
                    <div style={{ marginTop: 5 }}>Pedidos pendientes ({p.paraPedidos} pza):</div>
                    {p.pendientes.length === 0 && <div style={{ opacity: 0.7 }}>· ninguno</div>}
                    {p.pendientes.slice(0, 5).map((pd) => (
                      <div key={pd.folio}>· {pd.folio} — {pd.nombre}: {pd.qty}</div>
                    ))}
                    {p.pendientes.length > 5 && <div>· +{p.pendientes.length - 5} más</div>}
                    <div style={{ marginTop: 5 }}>+ Stock mínimo: {p.paraStock}</div>
                    <div>− En existencia: {p.usable}</div>
                    {p.enCamino > 0 && <div>− Por llegar (proveedor): {p.enCamino}</div>}
                    {p.existencia < 0 && <div style={{ opacity: 0.8, marginTop: 4 }}>(stock en sistema: {p.existencia}; el negativo de entregas viejas no se repone)</div>}
                  </span>
                </span>
              </div>
            ))}
            </>
          )}
        </Panel>

        <Panel title="Alertas de inventario">
          {bajos.length === 0 ? (
            <Empty icon="👍" text="Ningún sabor por debajo del mínimo." />
          ) : (
            bajos.map((p) => (
              <div key={p.sku} style={styles.listRow}>
                <span style={{ ...styles.dot, background: catColor(p.categoria) }} />
                <span style={{ flex: 1, fontWeight: 700 }}>{p.sabor}</span>
                <span className="pillbad" style={{
                  background: (stock[p.sku] ?? 0) <= 0 ? "#FBD8E5" : "#FDEECB",
                  color: (stock[p.sku] ?? 0) <= 0 ? "#D63384" : "#B4801B",
                }}>
                  {(stock[p.sku] ?? 0) <= 0 ? "agotado" : `${stock[p.sku]} pzas`}
                </span>
              </div>
            ))
          )}
        </Panel>
      </div>
    </div>
  );
}

function Kpi({ color, label, value }) {
  return (
    <div className="kpi" style={{ borderTop: `5px solid ${color}` }}>
      <div style={{ fontFamily: "'Baloo 2', cursive", fontSize: 30, color }}>{value}</div>
      <div style={styles.kpiLabel}>{label}</div>
    </div>
  );
}

// ---------------- PANEL: PEDIDOS ----------------
function Pedidos({ orders, onAdvance, onSet, onDelete, onEnvio, onPagado, onCampo, onDescuento, onEditItem, onRemoveItem, onEditCliente }) {
  const [f, setF] = useState("Todos");
  const [open, setOpen] = useState(null);
  const [editCli, setEditCli] = useState(null); // folio del pedido cuyo cliente se edita
  const list = f === "Todos" ? orders : orders.filter((o) => o.estatus === f);

  if (orders.length === 0) return <Empty big icon="📭" text="Aún no hay pedidos. Los que lleguen desde la tienda aparecerán aquí." />;

  return (
    <div className="fadeup">
      <div style={styles.chips}>
        {["Todos", ...ESTATUS, "Cancelado"].map((s) => (
          <Chip key={s} active={f === s} color={s === "Todos" ? "#F04E97" : (ESTATUS_COLOR[s] || "#F04E97")} onClick={() => setF(s)}>
            {s}
          </Chip>
        ))}
      </div>

      {list.length === 0 ? (
        <Empty icon="🔎" text="No hay pedidos en este estatus." />
      ) : (
        list.map((o) => {
          const isOpen = open === o.folio;
          const d = new Date(o.fecha);
          return (
            <div key={o.folio} className="ordercard">
              <div style={styles.orderHead} onClick={() => setOpen(isOpen ? null : o.folio)}>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={styles.orderFolio}>
                    {o.folio}
                    <span className="statebad" style={{ background: ESTATUS_COLOR[o.estatus] }}>{o.estatus}</span>
                    <span className="statebad" style={{ background: o.pagado ? "#2FB6A0" : "#D63384" }}>{o.pagado ? "Pagado" : "No pagado"}</span>
                  </div>
                  <div style={styles.orderSub}>
                    {o.cliente.nombre} · {o.items.reduce((a, i) => a + i.qty, 0)} pzas ·{" "}
                    {d.toLocaleDateString("es-MX", { day: "2-digit", month: "short" })}
                  </div>
                </div>
                <div style={{ fontFamily: "'Baloo 2', cursive", fontSize: 20, color: "#F04E97" }}>
                  {money(grandTotal(o))}
                </div>
                <span style={{ marginLeft: 10, color: "#c9b6c0", transform: isOpen ? "rotate(90deg)" : "none", transition: ".2s" }}>▸</span>
              </div>

              {isOpen && (
                <div style={styles.orderBody}>
                  <div style={styles.orderCols}>
                    <div style={{ flex: 1, minWidth: 220 }}>
                      <h4 style={styles.bodyH}>Productos</h4>
                      {o.items.map((it, idx) => (
                        <div key={idx} style={styles.miniRow}>
                          <span style={{ ...styles.dot, background: catColor(it.categoria) }} />
                          <span style={{ flex: 1 }}>{it.sabor}{it.granel ? ` · ${it.gramaje}` : ""}</span>
                          <input className="stockinp" style={{ width: 46 }} value={it.qty} inputMode="numeric"
                            onChange={(e) => onEditItem(o.folio, idx, e.target.value)} />
                          <span style={{ width: 60, textAlign: "right", fontWeight: 700 }}>{money(it.precio * it.qty)}</span>
                          <button className="stepbtn sm" title="Quitar" onClick={() => { if (window.confirm("¿Quitar " + it.sabor + " del pedido?")) onRemoveItem(o.folio, idx); }}>✕</button>
                        </div>
                      ))}
                      {o.notas && <div style={styles.notes}>📝 {o.notas}</div>}
                      <div style={styles.desglose}>
                        <div style={styles.desgRow}><span>Productos</span><span>{money(o.total)}</span></div>
                        <div style={styles.desgRow}>
                          <span>Envío</span>
                          <span>$<input className="stockinp" style={{ width: 64, marginLeft: 2 }} value={o.envio || 0} onChange={(e) => onEnvio(o.folio, e.target.value)} inputMode="numeric" /></span>
                        </div>
                        {comisionTarjeta(o) > 0 && (
                          <div style={styles.desgRow}><span>Comisión tarjeta (3.5%)</span><span>{money(comisionTarjeta(o))}</span></div>
                        )}
                        <div style={styles.desgRow}>
                          <span>Descuento / regalo</span>
                          <span>−$<input className="stockinp" style={{ width: 64, marginLeft: 2 }} value={o.descuento || 0} onChange={(e) => onDescuento(o.folio, e.target.value)} inputMode="numeric" /></span>
                        </div>
                        <div style={{ ...styles.desgRow, borderTop: "1px solid #eadfd3", paddingTop: 6, marginTop: 2 }}>
                          <span style={{ fontWeight: 800 }}>Total a cobrar</span>
                          <span style={{ fontFamily: "'Baloo 2', cursive", fontSize: 18, color: "#F04E97" }}>{money(grandTotal(o))}</span>
                        </div>
                      </div>
                      <div style={{ marginTop: 8, fontSize: 13, color: "#8a7683" }}>Pago: {o.pago}</div>
                      {o.vendedora && <div style={{ fontSize: 13, color: "#4A2C3A", fontWeight: 700 }}>👩‍💼 Vendedora: {o.vendedora}</div>}
                      {o.esDistribuidora && <div style={{ fontSize: 13, color: "#9B6FCE", fontWeight: 700 }}>🏷️ Distribuidora: {o.distribuidora} (núm. {o.distNum})</div>}
                      {o.nivel && <div style={{ fontSize: 13, color: "#8a7683" }}>Precio: {o.nivel}{o.unit != null ? ` (${money(o.unit)} c/u)` : " (precio por producto)"}</div>}
                      {o.cortesia
                        ? <div style={{ fontSize: 13, color: "#9B6FCE", fontWeight: 800 }}>🎁 Cortesía de Michelle (sin costo)</div>
                        : o.codigo && <div style={{ fontSize: 13, color: "#6e8f18", fontWeight: 700 }}>🎟️ Código: {o.codigo}</div>}
                    </div>
                    <div style={{ flex: 1, minWidth: 220 }}>
                      <h4 style={styles.bodyH}>Cliente y envío</h4>
                      <div style={styles.addr}>
                        <div><b>{o.cliente.nombre}</b></div>
                        <div>📞 {o.cliente.telefono}</div>
                        {o.cliente.correo && <div>✉️ {o.cliente.correo}</div>}
                        <div>{o.cliente.calle}</div>
                        <div>Col. {o.cliente.colonia}, C.P. {o.cliente.cp}</div>
                        <div>{o.cliente.estado}</div>
                        {o.cliente.referencias && <div style={{ color: "#8a7683" }}>Ref: {o.cliente.referencias}</div>}
                      </div>
                      <button className="ghost small" style={{ marginTop: 8 }} onClick={() => setEditCli(o.folio)}>✏️ Editar datos del cliente</button>
                      <div style={styles.guiaBox}>
                        <h4 style={{ ...styles.bodyH, margin: "0 0 8px" }}>Guía de envío</h4>
                        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                          <input
                            style={{ ...inp(), flex: "1 1 120px", padding: "8px 10px" }}
                            placeholder="Paquetería (ej. Estafeta)"
                            value={o.paqueteria || ""}
                            onChange={(e) => onCampo(o.folio, "paqueteria", e.target.value)}
                          />
                          <input
                            style={{ ...inp(), flex: "1 1 140px", padding: "8px 10px" }}
                            placeholder="Número de guía"
                            value={o.guia || ""}
                            onChange={(e) => onCampo(o.folio, "guia", e.target.value)}
                          />
                        </div>
                        <p style={{ fontSize: 12, color: "#8a7683", margin: "6px 2px 0" }}>
                          Al capturar la guía, el cliente podrá consultarla en “Rastrea tu pedido”.
                        </p>
                      </div>
                    </div>
                  </div>

                  <div style={styles.orderActions}>
                    <button
                      className="tabbtn"
                      style={o.pagado
                        ? { background: "#2FB6A0", color: "#fff", border: "2px solid #2FB6A0", boxShadow: "0 4px 0 #218a79" }
                        : { background: "#fff", color: "#D63384", border: "2px solid #f6cfdf", boxShadow: "0 4px 0 #f6cfdf" }}
                      onClick={() => onPagado(o.folio)}
                    >
                      {o.pagado ? "✓ Pagado" : "Marcar como pagado"}
                    </button>
                    {o.estatus !== "Entregado" && o.estatus !== "Cancelado" && (
                      <button className="cta small" onClick={() => onAdvance(o.folio)}>
                        Avanzar a “{ESTATUS[ESTATUS.indexOf(o.estatus) + 1]}”
                      </button>
                    )}
                    <select className="statusel" value={o.estatus} onChange={(e) => onSet(o.folio, e.target.value)}>
                      {[...ESTATUS, "Cancelado"].map((s) => <option key={s}>{s}</option>)}
                    </select>
                    <button className="ghost small danger" onClick={() => { if (confirm("¿Eliminar " + o.folio + "?")) onDelete(o.folio); }}>
                      Eliminar
                    </button>
                  </div>
                  {o.estatus === "Entregado" && (
                    <div style={styles.deducted}>✔ Inventario descontado al entregar</div>
                  )}
                </div>
              )}
            </div>
          );
        })
      )}

      {editCli && (() => {
        const o = orders.find((x) => x.folio === editCli);
        if (!o) return null;
        return (
          <ClienteEditor
            title={"Editar cliente · " + o.folio}
            data={o.cliente}
            onCancel={() => setEditCli(null)}
            onSave={(d) => { onEditCliente(o.folio, d); setEditCli(null); }}
          />
        );
      })()}
    </div>
  );
}

// ---------------- PANEL: INVENTARIO ----------------
function Inventario({ catalog, stock, committed, onSet, onBump }) {
  const [q, setQ] = useState("");
  const rows = catalog
    .filter((p) => (p.sabor + " " + p.categoria).toLowerCase().includes(q.toLowerCase()))
    .sort((a, b) => CAT_ORDER.indexOf(a.categoria) - CAT_ORDER.indexOf(b.categoria));

  return (
    <div className="fadeup">
      <input
        style={{ ...inp(), maxWidth: 320, marginBottom: 14 }}
        placeholder="Buscar sabor…"
        value={q}
        onChange={(e) => setQ(e.target.value)}
      />
      <div style={styles.invHead}>
        <span style={{ flex: 1 }}>Producto</span>
        <span style={styles.invCol}>Stock</span>
        <span style={styles.invCol2}>Ajustar</span>
        <span style={styles.invCol}>Comp.</span>
        <span style={styles.invCol}>Disp.</span>
        <span style={styles.invColBadge}>Estado</span>
      </div>
      {rows.map((p) => {
        const s = stock[p.sku] ?? 0;
        const comp = committed[p.sku] || 0;
        const disp = s - comp;
        let estado = { t: "OK", bg: "#EAF2CE", c: "#6e8f18" };
        if (!p.activo) estado = { t: "Pausado", bg: "#E9E2F4", c: "#7a5aa8" };
        else if (s <= 0) estado = { t: "Agotado", bg: "#FBD8E5", c: "#D63384" };
        else if (s < p.min) estado = { t: "Bajo", bg: "#FDEECB", c: "#B4801B" };
        return (
          <div key={p.sku} style={{ ...styles.invRow, opacity: p.activo ? 1 : 0.6 }}>
            <div style={{ flex: 1, display: "flex", alignItems: "center", gap: 8, minWidth: 0 }}>
              <span style={{ ...styles.dot, background: catColor(p.categoria) }} />
              <div style={{ minWidth: 0 }}>
                <div style={{ fontWeight: 700, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{p.sabor}</div>
                <div style={{ fontSize: 12, color: "#8a7683" }}>{p.categoria} · {p.gramaje}</div>
              </div>
            </div>
            <div style={styles.invCol}>
              <input
                className="stockinp"
                value={s}
                onChange={(e) => onSet(p.sku, e.target.value)}
                inputMode="numeric"
              />
            </div>
            <div style={styles.invCol2}>
              <button className="stepbtn sm" onClick={() => onBump(p.sku, -1)}>−</button>
              <button className="stepbtn sm plus" onClick={() => onBump(p.sku, 1)}>+</button>
              <button className="stepbtn sm five" onClick={() => onBump(p.sku, 5)}>+5</button>
            </div>
            <div style={{ ...styles.invCol, color: "#8a7683" }}>{comp}</div>
            <div style={{ ...styles.invCol, fontWeight: 800, color: disp < 0 ? "#D63384" : "#4A2C3A" }}>{disp}</div>
            <div style={styles.invColBadge}>
              <span className="pillbad" style={{ background: estado.bg, color: estado.c }}>{estado.t}</span>
            </div>
          </div>
        );
      })}
      <p style={styles.invNote}>
        <b>Comp.</b> = piezas comprometidas en pedidos sin entregar · <b>Disp.</b> = stock − comprometido.
        El stock se descuenta solo cuando marcas un pedido como “Entregado”.
      </p>
    </div>
  );
}

// ---------------- PANEL: CLIENTES ----------------
function Clientes({ orders, manuales, onUpdate, onDelete, onAdd }) {
  const [q, setQ] = useState("");
  const [editing, setEditing] = useState(null); // { key, data }
  const [creating, setCreating] = useState(false);
  const clientes = useMemo(() => {
    const map = {};
    orders.forEach((o) => {
      const key = o.cliente.telefono || o.cliente.correo || o.cliente.nombre;
      if (!map[key]) map[key] = { ...o.cliente, pedidos: 0, total: 0, ultima: o.fecha, vendedora: o.vendedora };
      map[key].pedidos += 1;
      map[key].total += grandTotal(o);
      if (new Date(o.fecha) > new Date(map[key].ultima)) { map[key].ultima = o.fecha; map[key].vendedora = o.vendedora; }
    });
    (manuales || []).forEach((c) => {
      const key = c.telefono || c.correo || c.nombre;
      if (!map[key]) map[key] = { ...c, pedidos: 0, total: 0, manual: true };
    });
    return Object.values(map).sort((a, b) => b.total - a.total);
  }, [orders, manuales]);

  const list = clientes.filter((c) =>
    (c.nombre + " " + c.telefono + " " + c.colonia + " " + c.estado).toLowerCase().includes(q.toLowerCase())
  );

  return (
    <div className="fadeup">
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center", marginBottom: 16 }}>
        <input
          style={{ ...inp(), maxWidth: 320, marginBottom: 0, flex: "1 1 220px" }}
          placeholder="Buscar por nombre, colonia, estado…"
          value={q}
          onChange={(e) => setQ(e.target.value)}
        />
        <button className="cta small" onClick={() => setCreating(true)}>➕ Nuevo cliente</button>
      </div>

      {clientes.length === 0 ? (
        <Empty icon="🧍" text="Aún no hay clientes. Registra uno con “Nuevo cliente” o llegarán solos con cada pedido." />
      ) : (
      <div style={styles.clientGrid}>
        {list.map((c, i) => {
          const key = c.telefono || c.correo || c.nombre;
          return (
            <div key={i} className="clientcard">
              <div style={styles.clientTop}>
                <div className="avatar">{c.nombre.charAt(0).toUpperCase()}</div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={styles.clientName}>{c.nombre}</div>
                  <div style={styles.clientMeta}>{c.manual && c.pedidos === 0 ? "Sin compras aún" : `${c.pedidos} pedido(s) · ${money(c.total)}`}</div>
                </div>
              </div>
              <div style={styles.clientBody}>
                <div>📞 {c.telefono}</div>
                {c.correo && <div>✉️ {c.correo}</div>}
                <div style={{ marginTop: 6, color: "#5a4450" }}>
                  {c.calle}<br />
                  Col. {c.colonia}, C.P. {c.cp}<br />
                  {c.estado}
                </div>
                {c.referencias && <div style={{ marginTop: 4, color: "#8a7683", fontSize: 13 }}>Ref: {c.referencias}</div>}
                {c.vendedora && <div style={{ marginTop: 6, fontSize: 13, fontWeight: 700, color: "#9B6FCE" }}>👩‍💼 {c.vendedora}</div>}
              </div>
              <div style={{ display: "flex", gap: 8, marginTop: 12, flexWrap: "wrap" }}>
                <button className="ghost small" onClick={() => setEditing({ key, data: { ...c } })}>
                  ✏️ Editar datos
                </button>
                <button
                  className="ghost small danger"
                  onClick={() => {
                    if (window.confirm(`¿Eliminar a ${c.nombre} y sus ${c.pedidos} pedido(s)? Esta acción no se puede deshacer.`)) onDelete(key);
                  }}
                >
                  🗑️ Eliminar
                </button>
              </div>
            </div>
          );
        })}
      </div>
      )}

      {editing && (
        <ClienteEditor
          data={editing.data}
          onCancel={() => setEditing(null)}
          onSave={(nuevo) => { onUpdate(editing.key, nuevo); setEditing(null); }}
        />
      )}
      {creating && (
        <ClienteEditor
          title="Nuevo cliente"
          data={{}}
          onCancel={() => setCreating(false)}
          onSave={(nuevo) => { onAdd(nuevo); setCreating(false); }}
        />
      )}
    </div>
  );
}

// ---- Editor de datos del cliente ----
function ClienteEditor({ data, title = "Editar cliente", onCancel, onSave }) {
  const [f, setF] = useState({
    nombre: data.nombre || "", telefono: data.telefono || "", correo: data.correo || "",
    calle: data.calle || "", colonia: data.colonia || "", cp: data.cp || "",
    estado: data.estado || "", referencias: data.referencias || "",
  });
  const [err, setErr] = useState({});
  const set = (k) => (e) => setF({ ...f, [k]: e.target.value });

  const save = () => {
    const e = {};
    if (!f.nombre.trim()) e.nombre = "Requerido";
    if (!/^\d{10}$/.test(f.telefono.replace(/\D/g, ""))) e.telefono = "10 dígitos";
    if (f.correo && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(f.correo)) e.correo = "Correo no válido";
    if (!f.calle.trim()) e.calle = "Requerido";
    if (!f.colonia.trim()) e.colonia = "Requerido";
    if (!/^\d{5}$/.test(f.cp)) e.cp = "5 dígitos";
    if (!f.estado) e.estado = "Requerido";
    setErr(e);
    if (Object.keys(e).length) return;
    onSave({
      nombre: f.nombre.trim(), telefono: f.telefono.trim(), correo: f.correo.trim(),
      calle: f.calle.trim(), colonia: f.colonia.trim(), cp: f.cp.trim(),
      estado: f.estado, referencias: f.referencias.trim(),
    });
  };

  return (
    <>
      <div style={styles.backdrop} onClick={onCancel} />
      <div style={styles.modal} className="popin">
        <div style={styles.modalHead}>
          <h2 style={styles.drawerTitle}>{title}</h2>
          <button className="closex" onClick={onCancel}>✕</button>
        </div>
        <div style={styles.form}>
          <Field label="Nombre completo" err={err.nombre}>
            <input style={inp(err.nombre)} value={f.nombre} onChange={set("nombre")} />
          </Field>
          <div style={styles.two}>
            <Field label="Teléfono" err={err.telefono}>
              <input style={inp(err.telefono)} value={f.telefono} onChange={set("telefono")} inputMode="numeric" />
            </Field>
            <Field label="Correo electrónico" err={err.correo}>
              <input style={inp(err.correo)} value={f.correo} onChange={set("correo")} />
            </Field>
          </div>
          <Field label="Calle y número" err={err.calle}>
            <input style={inp(err.calle)} value={f.calle} onChange={set("calle")} />
          </Field>
          <div style={styles.two}>
            <Field label="Colonia" err={err.colonia}>
              <input style={inp(err.colonia)} value={f.colonia} onChange={set("colonia")} />
            </Field>
            <Field label="Código postal" err={err.cp}>
              <input style={inp(err.cp)} value={f.cp} onChange={set("cp")} inputMode="numeric" maxLength={5} />
            </Field>
          </div>
          <Field label="Estado" err={err.estado}>
            <select style={inp(err.estado)} value={f.estado} onChange={set("estado")}>
              <option value="">Selecciona…</option>
              {ESTADOS_MX.map((e) => <option key={e} value={e}>{e}</option>)}
            </select>
          </Field>
          <Field label="Referencias (opcional)">
            <input style={inp()} value={f.referencias} onChange={set("referencias")} />
          </Field>
        </div>
        <div style={styles.modalFoot}>
          <button className="ghost" onClick={onCancel}>Cancelar</button>
          <button className="cta" onClick={save}>Guardar cambios</button>
        </div>
      </div>
    </>
  );
}

// ---------------- PANEL: VENDEDORAS ----------------
function Vendedoras({ orders }) {
  const data = useMemo(() => {
    const map = {};
    orders.forEach((o) => {
      if (o.estatus === "Cancelado") return;
      const v = o.vendedora || "Compra directa";
      if (!map[v]) map[v] = { nombre: v, pedidos: 0, total: 0, piezas: 0, clientes: new Set(), ultima: o.fecha };
      map[v].pedidos += 1;
      map[v].total += grandTotal(o);
      map[v].piezas += o.items.reduce((a, i) => a + i.qty, 0);
      map[v].clientes.add(o.cliente.telefono || o.cliente.correo || o.cliente.nombre);
      if (new Date(o.fecha) > new Date(map[v].ultima)) map[v].ultima = o.fecha;
    });
    return Object.values(map)
      .map((x) => ({ ...x, clientes: x.clientes.size }))
      .sort((a, b) => b.total - a.total);
  }, [orders]);

  if (data.length === 0)
    return <Empty big icon="👩‍💼" text="Aún no hay ventas registradas por vendedora. Cada pedido guarda quién ofreció las papitas." />;

  const totalGeneral = data.reduce((a, v) => a + v.total, 0);
  const colores = ["#F04E97", "#2FB6A0", "#F2A93B", "#9B6FCE", "#E8477E", "#9FC131", "#F0742B"];

  return (
    <div className="fadeup">
      <div style={styles.kpis}>
        <Kpi color="#F04E97" label="Vendedoras activas" value={data.filter((v) => v.nombre !== "Compra directa").length} />
        <Kpi color="#9FC131" label="Venta total" value={money(totalGeneral)} />
        <Kpi color="#2FB6A0" label="Pedidos" value={data.reduce((a, v) => a + v.pedidos, 0)} />
      </div>

      <div style={styles.clientGrid}>
        {data.map((v, i) => {
          const share = totalGeneral > 0 ? Math.round((v.total / totalGeneral) * 100) : 0;
          const col = colores[i % colores.length];
          return (
            <div key={v.nombre} className="clientcard">
              <div style={styles.clientTop}>
                <div className="avatar" style={{ background: col }}>{v.nombre.charAt(0).toUpperCase()}</div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={styles.clientName}>{v.nombre}</div>
                  <div style={styles.clientMeta}>{money(v.total)} · {share}% del total</div>
                </div>
              </div>
              <div style={styles.clientBody}>
                <div style={{ display: "flex", gap: 16, flexWrap: "wrap" }}>
                  <span>🧾 {v.pedidos} pedido(s)</span>
                  <span>🛍️ {v.piezas} pza</span>
                  <span>🧍 {v.clientes} cliente(s)</span>
                </div>
                <div style={{ marginTop: 10, height: 8, background: "#f2e6da", borderRadius: 999, overflow: "hidden" }}>
                  <div style={{ width: `${share}%`, height: "100%", background: col }} />
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ---------------- PANEL: PEDIDOS A PROVEEDOR ----------------
function Proveedores({ catalog, stock, committed, pedidos, onAdd, onRecibir, onDelete }) {
  const activos = catalog.filter((p) => p.activo);
  const porLlegar = useMemo(() => {
    const m = {};
    (pedidos || []).filter((o) => o.estatus === "Pendiente").forEach((o) => {
      Object.entries(o.items).forEach(([sku, q]) => { m[sku] = (m[sku] || 0) + q; });
    });
    return m;
  }, [pedidos]);

  const sugerido = (p) => Math.max(0, (committed[p.sku] || 0) + p.min - Math.max(0, stock[p.sku] ?? 0) - (porLlegar[p.sku] || 0));

  const [proveedor, setProveedor] = useState(PROVEEDORES[0] || "Otro");
  const [cant, setCant] = useState({});
  const reiniciar = () => {
    const o = {};
    activos.forEach((p) => { const s = sugerido(p); o[p.sku] = s > 0 ? String(s) : ""; });
    setCant(o);
  };
  useEffect(() => { reiniciar(); /* eslint-disable-next-line */ }, [pedidos, stock, committed]);

  const totalAPedir = activos.reduce((a, p) => a + (parseInt(cant[p.sku]) || 0), 0);

  const guardar = () => {
    const items = {};
    activos.forEach((p) => { const q = parseInt(cant[p.sku]) || 0; if (q > 0) items[p.sku] = q; });
    if (Object.keys(items).length === 0) return;
    onAdd({ proveedor, items });
    const o = {}; activos.forEach((p) => { o[p.sku] = ""; }); setCant(o);
  };

  const nombreSku = (sku) => { const p = catalog.find((x) => x.sku === sku); return p ? p.sabor : sku; };

  return (
    <div className="fadeup">
      {/* armar pedido a proveedor */}
      <div style={styles.softPanel}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap", marginBottom: 12 }}>
          <h3 style={{ ...styles.panelTitle, margin: 0 }}>Nuevo pedido a proveedor</h3>
          <select className="statusel" value={proveedor} onChange={(e) => setProveedor(e.target.value)}>
            {PROVEEDORES.map((pr) => <option key={pr}>{pr}</option>)}
          </select>
          <button className="ghost small" onClick={reiniciar}>↺ Usar sugerido</button>
          <button className="cta small" style={{ marginLeft: "auto" }} onClick={guardar}>Registrar pedido ({totalAPedir})</button>
        </div>

        <div style={styles.invHead}>
          <span style={{ flex: 1 }}>Producto</span>
          <span style={styles.invCol}>Stock</span>
          <span style={styles.invCol}>Pedidos</span>
          <span style={styles.invCol}>Por llegar</span>
          <span style={styles.invCol}>A pedir</span>
        </div>
        {activos.map((p) => {
          const s = stock[p.sku] ?? 0;
          const comp = committed[p.sku] || 0;
          const cam = porLlegar[p.sku] || 0;
          const sug = sugerido(p);
          return (
            <div key={p.sku} style={{ ...styles.invRow, opacity: sug > 0 ? 1 : 0.65 }}>
              <div style={{ flex: 1, display: "flex", alignItems: "center", gap: 8, minWidth: 0 }}>
                <span style={{ ...styles.dot, background: catColor(p.categoria) }} />
                <div style={{ fontWeight: 700, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{p.sabor}</div>
              </div>
              <div style={{ ...styles.invCol, color: s < 0 ? "#D63384" : "#4A2C3A", fontWeight: 700 }}>{s}</div>
              <div style={{ ...styles.invCol, color: "#8a7683" }}>{comp}</div>
              <div style={{ ...styles.invCol, color: "#2FB6A0", fontWeight: 700 }}>{cam || "—"}</div>
              <div style={styles.invCol}>
                <input className="stockinp" value={cant[p.sku] || ""} placeholder="0"
                  onChange={(e) => setCant({ ...cant, [p.sku]: e.target.value.replace(/\D/g, "") })} inputMode="numeric" />
              </div>
            </div>
          );
        })}
        <p style={styles.invNote}>
          <b>A pedir</b> se sugiere solo: pedidos comprometidos + stock mínimo − existencia − por llegar. Ajusta lo que quieras y registra.
        </p>
      </div>

      {/* pedidos a proveedor registrados */}
      <h3 style={{ ...styles.panelTitle, margin: "22px 0 10px" }}>Pedidos a proveedor</h3>
      {(pedidos || []).length === 0 ? (
        <Empty icon="📦" text="Aún no hay pedidos a proveedor. Registra el primero arriba." />
      ) : (
        pedidos.map((o) => {
          const totalPzas = Object.values(o.items).reduce((a, q) => a + q, 0);
          const fecha = new Date(o.fecha).toLocaleDateString("es-MX", { day: "2-digit", month: "short", year: "numeric" });
          return (
            <div key={o.folio} className="ordercard">
              <div style={{ padding: "14px 16px" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 6 }}>
                  <span style={{ fontFamily: "'Baloo 2', cursive", fontSize: 18 }}>{o.folio}</span>
                  <span className="statebad" style={{ background: o.estatus === "Recibido" ? "#9FC131" : "#F2A93B" }}>{o.estatus}</span>
                  <span style={{ color: "#8a7683", fontSize: 13 }}>{o.proveedor} · {fecha} · {totalPzas} pza</span>
                </div>
                <div style={{ fontSize: 14, color: "#5a4450", lineHeight: 1.6 }}>
                  {Object.entries(o.items).map(([sku, q]) => `${nombreSku(sku)}: ${q}`).join(" · ")}
                </div>
                <div style={{ display: "flex", gap: 8, marginTop: 12, flexWrap: "wrap" }}>
                  {o.estatus !== "Recibido" && (
                    <button className="cta small" onClick={() => onRecibir(o.folio)}>✓ Marcar recibido (suma a stock)</button>
                  )}
                  <button className="ghost small danger" onClick={() => { if (window.confirm("¿Eliminar " + o.folio + "?")) onDelete(o.folio); }}>Eliminar</button>
                </div>
                {o.estatus === "Recibido" && <div style={{ marginTop: 8, color: "#6e8f18", fontWeight: 700, fontSize: 13 }}>✔ Sumado a tu inventario</div>}
              </div>
            </div>
          );
        })
      )}
    </div>
  );
}

// ---------------- VISTA: BOLETÍN (tiempo real) ----------------
function Boletin() {
  const [rows, setRows] = useState([])
  const [cargando, setCargando] = useState(true)

  const cargar = async () => {
    if (!supabase) { setCargando(false); return }
    const { data } = await supabase.from("pedidos_dist").select("sabor,categoria,cantidad")
    const map = {}
    ;(data || []).forEach((r) => { if (!r.sabor) return; if (!map[r.sabor]) map[r.sabor] = { sabor: r.sabor, categoria: r.categoria, piezas: 0 }; map[r.sabor].piezas += r.cantidad })
    setRows(Object.values(map).sort((a, b) => b.piezas - a.piezas))
    setCargando(false)
  }
  useEffect(() => {
    cargar()
    if (!supabase) return
    const ch = supabase.channel("boletin").on("postgres_changes", { event: "*", schema: "public", table: "pedidos_dist" }, cargar).subscribe()
    return () => supabase.removeChannel(ch)
  }, [])

  const max = rows.length ? rows[0].piezas : 1

  return (
    <div className="fadeup">
      <section style={{ textAlign: "center", padding: "18px 0 6px" }}>
        <span className="promo-pill" style={{ display: "inline-block", marginBottom: 10 }}>En tiempo real ⚡</span>
        <h1 style={styles.heroTitle}>Los más vendidos ahora mismo</h1>
        <p style={styles.heroSub}>Ranking de sabores según lo que están moviendo las distribuidoras. Se actualiza solo.</p>
      </section>
      {!supabase ? (
        <Empty icon="☁️" text="Conecta Supabase (Fase 2) para ver el boletín en tiempo real." />
      ) : cargando ? (
        <Empty icon="⏳" text="Cargando el boletín…" />
      ) : rows.length === 0 ? (
        <Empty icon="📊" text="Aún no hay movimientos registrados. En cuanto las distribuidoras pidan, aparecerán aquí." />
      ) : (
        <div style={{ maxWidth: 620, margin: "0 auto" }}>
          {rows.slice(0, 12).map((r, i) => (
            <div key={r.sabor} className="card" style={{ marginBottom: 10, padding: "12px 16px" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <span style={{ fontFamily: "'Baloo 2', cursive", fontSize: 22, color: i < 3 ? "#F04E97" : "#c9b6c0", width: 32 }}>{i + 1}</span>
                <span style={{ ...styles.dot, background: catColor(r.categoria) }} />
                <span style={{ flex: 1, fontWeight: 800 }}>{r.sabor}</span>
                <span style={{ fontFamily: "'Baloo 2', cursive", color: "#4A2C3A" }}>{r.piezas} pza</span>
              </div>
              <div style={{ marginTop: 8, height: 8, background: "#f2e6da", borderRadius: 999, overflow: "hidden" }}>
                <div style={{ width: `${Math.round((r.piezas / max) * 100)}%`, height: "100%", background: catColor(r.categoria) }} />
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

// ---------------- VISTA: MI PANEL (distribuidora, tiempo real) ----------------
const hashClave = (s) => { let h = 5381; for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0; return "h" + h.toString(36); }
function MiPanel() {
  const money = (n) => "$" + Math.round(n || 0).toLocaleString("es-MX")
  const [codigo, setCodigo] = useState(() => { try { return localStorage.getItem("mi_codigo_dist") || "" } catch (e) { return "" } })
  const [activo, setActivo] = useState(() => { try { return !!localStorage.getItem("mi_codigo_dist") } catch (e) { return false } })
  const [rows, setRows] = useState([])
  const [cargando, setCargando] = useState(false)
  // login / creación de acceso de distribuidora
  const [modo, setModo] = useState("login") // login | crear
  const [fUser, setFUser] = useState("")
  const [fPass, setFPass] = useState("")
  const [fCode, setFCode] = useState("")
  const [msg, setMsg] = useState("")
  const [ocupado, setOcupado] = useState(false)

  const login = async () => {
    if (!supabase) return
    const u = fUser.trim().toLowerCase()
    if (!u || !fPass) { setMsg("Escribe tu usuario y contraseña"); return }
    setOcupado(true); setMsg("")
    const { data } = await supabase.from("distribuidoras").select("codigo,usuario,clave").eq("usuario", u).limit(1)
    const row = data && data[0]
    setOcupado(false)
    if (!row || row.clave !== hashClave(fPass)) { setMsg("Usuario o contraseña incorrectos"); return }
    try { localStorage.setItem("mi_codigo_dist", row.codigo) } catch (e) {}
    setCodigo(row.codigo); setActivo(true)
  }
  const crearAcceso = async () => {
    if (!supabase) return
    const c = fCode.trim().toUpperCase().replace(/\s+/g, "")
    const u = fUser.trim().toLowerCase()
    if (!c || !u || !fPass) { setMsg("Llena tu código, usuario y contraseña"); return }
    if (fPass.length < 4) { setMsg("La contraseña debe tener al menos 4 caracteres"); return }
    setOcupado(true); setMsg("")
    const { data: found } = await supabase.from("distribuidoras").select("codigo").eq("codigo", c).limit(1)
    if (!found || !found.length) { setOcupado(false); setMsg("Ese código no existe. Regístrate primero en “Quiero ser distribuidor”."); return }
    const { data: taken } = await supabase.from("distribuidoras").select("codigo").eq("usuario", u).neq("codigo", c).limit(1)
    if (taken && taken.length) { setOcupado(false); setMsg("Ese usuario ya está en uso, elige otro"); return }
    const { error } = await supabase.from("distribuidoras").update({ usuario: u, clave: hashClave(fPass) }).eq("codigo", c)
    setOcupado(false)
    if (error) { setMsg("No se pudo crear tu acceso, intenta de nuevo"); return }
    try { localStorage.setItem("mi_codigo_dist", c) } catch (e) {}
    setCodigo(c); setActivo(true)
  }

  const cargar = async (cod) => {
    if (!supabase || !cod) return
    setCargando(true)
    const { data } = await supabase.from("pedidos_dist").select("*").eq("codigo", cod).order("fecha", { ascending: false })
    setRows(data || [])
    setCargando(false)
  }
  useEffect(() => {
    if (!activo || !codigo) return
    cargar(codigo)
    if (!supabase) return
    const ch = supabase.channel("mipanel_" + codigo).on("postgres_changes", { event: "*", schema: "public", table: "pedidos_dist", filter: `codigo=eq.${codigo}` }, () => cargar(codigo)).subscribe()
    return () => supabase.removeChannel(ch)
  }, [activo, codigo])

  const salir = () => { try { localStorage.removeItem("mi_codigo_dist") } catch (e) {} setActivo(false); setCodigo(""); setRows([]); setFUser(""); setFPass(""); setFCode(""); setMsg("") }

  const k = useMemo(() => {
    let piezas = 0, costo = 0, ganancia = 0
    rows.forEach((r) => { piezas += r.cantidad; costo += r.cantidad * r.costo_unit; ganancia += r.cantidad * (50 - r.costo_unit) })
    return { piezas, costo, ganancia }
  }, [rows])
  const porMes = useMemo(() => {
    const map = {}
    rows.forEach((r) => { const key = (r.fecha || "").slice(0, 7); if (!map[key]) map[key] = { mes: key, piezas: 0, ganancia: 0 }; map[key].piezas += r.cantidad; map[key].ganancia += r.cantidad * (50 - r.costo_unit) })
    return Object.values(map).sort((a, b) => a.mes.localeCompare(b.mes))
  }, [rows])
  const topSabor = useMemo(() => {
    const map = {}; rows.forEach((r) => { map[r.sabor] = (map[r.sabor] || 0) + r.cantidad })
    const arr = Object.entries(map).sort((a, b) => b[1] - a[1]); return arr.length ? arr[0][0] : "—"
  }, [rows])

  if (!supabase) return (
    <div className="fadeup"><Empty big icon="☁️" text="Conecta Supabase (Fase 2) para que las distribuidoras vean su panel en tiempo real." /></div>
  )

  if (!activo) return (
    <div className="fadeup">
      <section style={{ textAlign: "center", padding: "18px 0 10px" }}>
        <h1 style={styles.heroTitle}>Mi tablero de distribuidora</h1>
        <p style={styles.heroSub}>Entra con tu usuario para ver cuántas papitas moviste, a qué precio y tu ganancia estimada.</p>
      </section>
      <div style={styles.rastrearCard}>
        <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
          <button className="tabbtn" style={modo === "login" ? styles.ptabActive : styles.ptabIdle} onClick={() => { setModo("login"); setMsg("") }}>Iniciar sesión</button>
          <button className="tabbtn" style={modo === "crear" ? styles.ptabActive : styles.ptabIdle} onClick={() => { setModo("crear"); setMsg("") }}>Crear mi acceso</button>
        </div>

        {modo === "login" ? (
          <>
            <input style={{ ...inp(), marginBottom: 10 }} placeholder="Usuario" autoCapitalize="none" value={fUser} onChange={(e) => setFUser(e.target.value)} />
            <input style={inp()} type="password" placeholder="Contraseña" value={fPass} onChange={(e) => setFPass(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") login() }} />
            <button className="cta" style={{ width: "100%", marginTop: 14 }} onClick={login} disabled={ocupado}>{ocupado ? "Entrando…" : "Entrar"}</button>
            <p style={{ fontSize: 12, color: "#8a7683", marginTop: 10 }}>¿Primera vez? Toca “Crear mi acceso” y usa el código que te dio la página al registrarte.</p>
          </>
        ) : (
          <>
            <input style={{ ...inp(), marginBottom: 10 }} placeholder="Tu código de distribuidora (ej. 111)" value={fCode} onChange={(e) => setFCode(e.target.value)} />
            <input style={{ ...inp(), marginBottom: 10 }} placeholder="Elige tu usuario" autoCapitalize="none" value={fUser} onChange={(e) => setFUser(e.target.value)} />
            <input style={inp()} type="password" placeholder="Elige tu contraseña" value={fPass} onChange={(e) => setFPass(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") crearAcceso() }} />
            <button className="cta" style={{ width: "100%", marginTop: 14 }} onClick={crearAcceso} disabled={ocupado}>{ocupado ? "Creando…" : "Crear mi acceso"}</button>
            <p style={{ fontSize: 12, color: "#8a7683", marginTop: 10 }}>¿Aún no tienes código? Regístrate en “Quiero ser distribuidor”.</p>
          </>
        )}
        {msg && <div style={{ color: "#D63384", fontWeight: 700, fontSize: 13, marginTop: 10 }}>{msg}</div>}
      </div>
    </div>
  )

  return (
    <div className="fadeup">
      <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap", marginBottom: 14 }}>
        <span className="badge" style={{ background: "#9B6FCE", color: "#fff", fontWeight: 800, fontSize: 12, padding: "4px 10px", borderRadius: 999 }}>Código {codigo}</span>
        <button className="ghost small" onClick={salir}>Cerrar sesión</button>
      </div>
      <div style={styles.kpis}>
        <div className="kpi-c" style={{ ...kpiBox, borderTop: "5px solid #F2A93B" }}><div style={kpiV("#F2A93B")}>{k.piezas}</div><div style={kpiL}>Piezas movidas</div></div>
        <div className="kpi-c" style={{ ...kpiBox, borderTop: "5px solid #E8477E" }}><div style={kpiV("#E8477E")}>{money(k.costo)}</div><div style={kpiL}>Te costaron</div></div>
        <div className="kpi-c" style={{ ...kpiBox, borderTop: "5px solid #9FC131" }}><div style={kpiV("#6e8f18")}>{money(k.ganancia)}</div><div style={kpiL}>Ganancia estimada</div></div>
        <div className="kpi-c" style={{ ...kpiBox, borderTop: "5px solid #9B6FCE" }}><div style={{ ...kpiV("#9B6FCE"), fontSize: 20 }}>{topSabor}</div><div style={kpiL}>Tu sabor top</div></div>
      </div>
      <p style={{ fontSize: 12, color: "#8a7683", margin: "-6px 2px 16px" }}>
        * Ganancia estimada suponiendo que vendes al público a $50 por bolsa (ganancia = $50 − tu costo).
      </p>

      <div style={styles.softPanel}>
        <h3 style={styles.panelTitle}>Tu mes a mes</h3>
        {porMes.length === 0 ? <Empty icon="📅" text="Aún no tienes movimientos." /> : (
          porMes.map((m) => (
            <div key={m.mes} style={styles.listRow}>
              <span style={{ flex: 1, fontWeight: 700 }}>{m.mes}</span>
              <span style={{ color: "#8a7683", marginRight: 12 }}>{m.piezas} pza</span>
              <span style={{ fontFamily: "'Baloo 2', cursive", color: "#6e8f18" }}>{money(m.ganancia)}</span>
            </div>
          ))
        )}
      </div>
    </div>
  )
}
const kpiBox = { background: "#fff", borderRadius: 18, padding: 16, boxShadow: "0 6px 16px rgba(224,120,160,.12)" }
const kpiV = (c) => ({ fontFamily: "'Baloo 2', cursive", fontSize: 26, color: c, lineHeight: 1 })
const kpiL = { fontSize: 13, color: "#7a6570", fontWeight: 700, marginTop: 4 }

// ---------------- VISTA: RASTREA TU PEDIDO ----------------
function RastrearView({ orders }) {
  const [q, setQ] = useState("");
  const [buscado, setBuscado] = useState(false);

  const resultados = useMemo(() => {
    const term = q.trim().toLowerCase();
    const digitos = q.replace(/\D/g, "");
    if (!term) return [];
    return orders.filter((o) =>
      o.folio.toLowerCase() === term ||
      (digitos.length >= 10 && (o.cliente.telefono || "").replace(/\D/g, "") === digitos)
    );
  }, [q, orders]);

  const buscar = () => setBuscado(true);

  return (
    <div className="fadeup">
      <section style={{ textAlign: "center", padding: "18px 0 10px" }}>
        <h1 style={styles.heroTitle}>Rastrea tu pedido</h1>
        <p style={styles.heroSub}>
          Escribe tu <b>folio</b> (ej. PED-0001) o tu <b>número de teléfono</b> para ver el estatus de tu
          pedido y tu número de guía.
        </p>
      </section>

      <div style={styles.rastrearCard}>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          <input
            style={{ ...inp(), flex: "1 1 200px" }}
            placeholder="Folio o teléfono"
            value={q}
            onChange={(e) => { setQ(e.target.value); setBuscado(false); }}
            onKeyDown={(e) => { if (e.key === "Enter") buscar(); }}
          />
          <button className="cta" onClick={buscar}>Buscar</button>
        </div>

        {buscado && resultados.length === 0 && (
          <div style={{ textAlign: "center", padding: "24px 8px", color: "#8a7683" }}>
            <div style={{ fontSize: 40 }}>🔎</div>
            <p style={{ fontWeight: 700, marginTop: 8 }}>No encontramos un pedido con esos datos.</p>
            <p style={{ fontSize: 13 }}>Revisa tu folio o teléfono, o escríbenos por WhatsApp.</p>
          </div>
        )}

        {buscado && resultados.map((o) => (
          <div key={o.folio} style={styles.rastreoRow}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 8 }}>
              <span style={{ fontFamily: "'Baloo 2', cursive", fontSize: 18 }}>{o.folio}</span>
              <span className="statebad" style={{ background: ESTATUS_COLOR[o.estatus] }}>{o.estatus}</span>
            </div>
            <div style={{ fontSize: 14, color: "#5a4450" }}>
              Hola <b>{o.cliente.nombre.split(" ")[0]}</b>, tu pedido de {o.items.reduce((a, i) => a + i.qty, 0)} pza va así:
            </div>
            <div style={styles.rastreoGuia}>
              {o.guia ? (
                <>
                  <div>🚚 Paquetería: <b>{o.paqueteria || "Por definir"}</b></div>
                  <div>🔖 Número de guía: <b style={{ color: "#F04E97" }}>{o.guia}</b></div>
                </>
              ) : (
                <div style={{ color: "#8a7683" }}>
                  📦 Tu guía aún no está lista. En cuanto generemos tu envío, aquí aparecerá tu número de guía.
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ---------------- VISTA: QUIERO SER DISTRIBUIDOR ----------------
const DIST_ESTATUS = ["Nuevo", "Contactado", "Activo", "Descartado"];
const DIST_COLOR = { "Nuevo": "#F04E97", "Contactado": "#F2A93B", "Activo": "#9FC131", "Descartado": "#9AA0A6" };

function DistribuidorView({ onSubmit, onRegistrar, onGoTienda }) {
  const [f, setF] = useState({
    nombre: "", negocio: "", telefono: "", correo: "", estado: "", ciudad: "",
    tipo: "", volumen: "", canal: "", mensaje: "",
  });
  const [err, setErr] = useState({});
  const [done, setDone] = useState(null); // { folio, codigo }
  const [enviando, setEnviando] = useState(false);
  const set = (k) => (e) => setF({ ...f, [k]: e.target.value });

  const validate = () => {
    const e = {};
    if (!f.nombre.trim()) e.nombre = "Escribe tu nombre";
    if (!/^\d{10}$/.test(f.telefono.replace(/\D/g, ""))) e.telefono = "10 dígitos";
    if (f.correo && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(f.correo)) e.correo = "Correo no válido";
    if (!f.estado) e.estado = "Elige tu estado";
    setErr(e);
    return Object.keys(e).length === 0;
  };
  const submit = async () => {
    if (!validate()) return;
    setEnviando(true);
    const datos = {
      nombre: f.nombre.trim(), negocio: f.negocio.trim(), telefono: f.telefono.trim(),
      correo: f.correo.trim(), estado: f.estado, ciudad: f.ciudad.trim(),
      tipo: f.tipo, volumen: f.volumen, canal: f.canal.trim(), mensaje: f.mensaje.trim(),
    };
    const folio = onSubmit(datos);
    let codigo = null;
    if (onRegistrar) { try { codigo = await onRegistrar(datos); } catch (e) { codigo = null; } }
    setEnviando(false);
    setDone({ folio, codigo });
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  if (done) {
    return (
      <div className="fadeup" style={{ textAlign: "center", padding: "48px 16px", maxWidth: 560, margin: "0 auto" }}>
        <div style={{ fontSize: 60 }}>🎉</div>
        <h1 style={{ fontFamily: "'Baloo 2', cursive", fontSize: 32, color: "#F04E97", margin: "8px 0 6px" }}>
          ¡Bienvenida distribuidora!
        </h1>
        {done.codigo ? (
          <>
            <p style={{ fontSize: 16, color: "#7a6570", lineHeight: 1.5, marginBottom: 14 }}>
              Este es tu <b>código provisional</b> de distribuidora. Guárdalo: con él activas tu
              precio y puedes empezar a hacer tus pedidos en la tienda.
            </p>
            <div style={{ display: "inline-block", background: "#F5EEFB", border: "2px solid #E9E2F4", borderRadius: 16, padding: "14px 28px" }}>
              <div style={{ fontSize: 12, color: "#7a5aa8", fontWeight: 800 }}>TU CÓDIGO</div>
              <div style={{ fontFamily: "'Baloo 2', cursive", fontSize: 40, color: "#9B6FCE", letterSpacing: 3 }}>{done.codigo}</div>
            </div>
            <p style={{ fontSize: 13, color: "#8a7683", marginTop: 14, maxWidth: 420, marginLeft: "auto", marginRight: "auto" }}>
              En la tienda activa “Soy distribuidora” y escribe tu código. Tu precio inicial es
              provisional; te confirmaremos tus precios finales por WhatsApp.
            </p>

            {/* invitación especial por WhatsApp */}
            <div style={{ marginTop: 22, background: "#E9F9F4", border: "2px solid #CDEFE6", borderRadius: 18, padding: "18px 20px", maxWidth: 460, marginLeft: "auto", marginRight: "auto" }}>
              <div style={{ fontSize: 30 }}>💚</div>
              <h3 style={{ fontFamily: "'Baloo 2', cursive", fontSize: 20, color: "#1f8f78", margin: "4px 0 6px" }}>Tu lugar especial de distribuidora</h3>
              <p style={{ fontSize: 14, color: "#3a6a60", lineHeight: 1.5, margin: "0 0 14px" }}>
                Escríbenos para guardar tu contacto y compartirte marketing, ideas, promociones y
                todo el material exclusivo para distribuidoras. ¡Queremos ayudarte a vender más! 💕
              </p>
              <a
                className="cta"
                href={`https://wa.me/${WHATSAPP_TIENDA}?text=${encodeURIComponent(
                  "¡Hola! Soy " + (f.nombre || "una nueva distribuidora") + " 🎉 Me acabo de registrar como distribuidora de Papitas Saludables. Mi código es " + done.codigo + ". Quiero que guardes mi contacto para recibir marketing, ideas y promociones para distribuidoras 💕"
                )}`}
                target="_blank"
                rel="noreferrer"
                style={{ display: "inline-block", textDecoration: "none", background: "#25D366" }}
              >
                📲 Escríbenos por WhatsApp
              </a>
            </div>
          </>
        ) : (
          <p style={{ fontSize: 16, color: "#7a6570", lineHeight: 1.5 }}>
            Gracias por tu interés. Guardamos tus datos (folio <b>{done.folio}</b>) y te
            contactaremos muy pronto por WhatsApp o correo con tu código y tus precios.
          </p>
        )}
        <div style={{ marginTop: 22 }}><button className="cta" onClick={onGoTienda}>Ir a la tienda</button></div>
      </div>
    );
  }

  return (
    <div className="fadeup">
      <section style={{ textAlign: "center", padding: "18px 0 6px" }}>
        <span className="promo-pill" style={{ display: "inline-block", marginBottom: 12 }}>Programa de distribuidores</span>
        <h1 style={styles.heroTitle}>Vende Papitas Saludables en tu zona</h1>
        <p style={styles.heroSub}>
          Déjanos tus datos y el estado desde donde nos escribes. Te enviamos la lista de precios
          preferenciales de distribuidor para que empieces a revender con buen margen.
        </p>
      </section>

      {/* beneficios */}
      <div style={styles.benefits}>
        <Benefit color="#F04E97" icon="🏷️" title="Precio preferencial" text="Tu mejor precio por volumen: desde $36.50 por bolsa, frente a $50 al público." />
        <Benefit color="#2FB6A0" icon="📦" title="Catálogo completo" text="Acceso a todos los sabores y presentaciones disponibles." />
        <Benefit color="#F2A93B" icon="📈" title="Escala tu compra" text="Mejores condiciones y prioridad de surtido conforme crece tu volumen." />
        <Benefit color="#9B6FCE" icon="🤝" title="Acompañamiento" text="Te asesoramos con surtido y reabasto según tu demanda." />
        <Benefit color="#E8477E" icon="🥕" title="Producto que se vende" text="Botana natural deshidratada, sin freír. Sabores que enganchan y repiten." />
        <Benefit color="#9FC131" icon="📸" title="Material para vender" text="Te compartimos fotos y contenido listo para promocionar en tus redes." />
      </div>

      {/* precios por volumen */}
      <div style={styles.priceCard}>
        <h2 style={{ fontFamily: "'Baloo 2', cursive", fontSize: 24, margin: "0 0 2px" }}>Precios por volumen</h2>
        <p style={{ color: "#8a7683", fontSize: 14, margin: "0 0 16px" }}>
          Mientras más piezas, mejor precio por bolsa. Menos de 25 piezas: precio público $50.
        </p>
        <div style={styles.volGrid}>
          {VOLUMEN.map((t) => (
            <div key={t.min} style={{ ...styles.volItem, borderColor: t.destacado ? "#F04E97" : "#f2e6da" }}>
              <div style={styles.volImgWrap}>
                <img src={t.img} alt={`${t.min} piezas o más`} style={styles.volImg} />
                {t.destacado && <span className="minbadge">Precio mínimo</span>}
                <span className="offbadge">−{t.off}</span>
              </div>
              <div style={styles.volBody}>
                <div style={styles.volQty}>{t.min}+ piezas</div>
                <div style={styles.volPrice}>
                  {money(t.precio)}<span style={{ fontSize: 13, color: "#8a7683", fontFamily: "'Nunito',sans-serif" }}> c/u</span>
                </div>
              </div>
            </div>
          ))}
        </div>
        <p style={{ color: "#a08a96", fontSize: 12, marginTop: 14 }}>
          Precios sujetos a cambio. Los precios finales de distribuidor se confirman al registrarte.
        </p>
      </div>

      {/* formulario */}
      <div style={styles.distFormWrap}>
        <h2 style={{ fontFamily: "'Baloo 2', cursive", fontSize: 24, margin: "0 0 4px" }}>Déjanos tus datos</h2>
        <p style={{ color: "#8a7683", fontSize: 14, margin: "0 0 14px" }}>
          Los campos con <b style={{ color: "#E8477E" }}>*</b> son obligatorios.
        </p>

        <div style={styles.form2}>
          <Field label="Nombre completo *" err={err.nombre}>
            <input style={inp(err.nombre)} value={f.nombre} onChange={set("nombre")} placeholder="Tu nombre" />
          </Field>
          <Field label="Nombre del negocio (opcional)">
            <input style={inp()} value={f.negocio} onChange={set("negocio")} placeholder="Ej. Dulcería La Esquina" />
          </Field>
          <Field label="Teléfono / WhatsApp *" err={err.telefono}>
            <input style={inp(err.telefono)} value={f.telefono} onChange={set("telefono")} inputMode="numeric" placeholder="10 dígitos" />
          </Field>
          <Field label="Correo electrónico" err={err.correo}>
            <input style={inp(err.correo)} value={f.correo} onChange={set("correo")} placeholder="correo@ejemplo.com" />
          </Field>
          <Field label="Estado desde donde escribes *" err={err.estado}>
            <select style={inp(err.estado)} value={f.estado} onChange={set("estado")}>
              <option value="">Selecciona…</option>
              {ESTADOS_MX.map((e) => <option key={e} value={e}>{e}</option>)}
            </select>
          </Field>
          <Field label="Ciudad o municipio (opcional)">
            <input style={inp()} value={f.ciudad} onChange={set("ciudad")} placeholder="Ej. Guadalajara" />
          </Field>
          <Field label="¿Tienes un negocio? (opcional)">
            <select style={inp()} value={f.tipo} onChange={set("tipo")}>
              <option value="">Selecciona…</option>
              <option>Tienda física</option>
              <option>Venta en línea / redes</option>
              <option>Venta directa / catálogo</option>
              <option>Apenas voy a empezar</option>
              <option>Otro</option>
            </select>
          </Field>
          <Field label="Compra estimada al mes (opcional)">
            <select style={inp()} value={f.volumen} onChange={set("volumen")}>
              <option value="">Selecciona…</option>
              <option>Menos de 25 piezas</option>
              <option>25 a 64 piezas</option>
              <option>65 a 129 piezas</option>
              <option>130 piezas o más</option>
            </select>
          </Field>
        </div>
        <div style={{ marginTop: 12 }}>
          <Field label="Cuéntanos dónde y cómo planeas vender (opcional)">
            <textarea style={{ ...inp(), minHeight: 84, resize: "vertical" }} value={f.mensaje} onChange={set("mensaje")}
              placeholder="Ej. Quiero vender en mi papelería y por Facebook en mi colonia…" />
          </Field>
        </div>

        <button className="cta" style={{ marginTop: 16, width: "100%" }} onClick={submit} disabled={enviando}>
          {enviando ? "Generando tu código…" : "Quiero ser distribuidora · generar mi código →"}
        </button>
      </div>
    </div>
  );
}

function Benefit({ color, icon, title, text }) {
  return (
    <div style={{ ...styles.benefit, borderTop: `5px solid ${color}` }}>
      <div style={{ fontSize: 30 }}>{icon}</div>
      <div style={{ fontFamily: "'Baloo 2', cursive", fontSize: 17, margin: "6px 0 2px" }}>{title}</div>
      <div style={{ fontSize: 13.5, color: "#7a6570", lineHeight: 1.4 }}>{text}</div>
    </div>
  );
}

// ---------------- PANEL: DISTRIBUIDORES ----------------
function Distribuidores({ distribs, onSet, onDelete }) {
  const [q, setQ] = useState("");
  const [fil, setFil] = useState("Todos");

  let list = distribs;
  if (fil !== "Todos") list = list.filter((d) => d.estatus === fil);
  list = list.filter((d) =>
    (d.nombre + " " + (d.negocio || "") + " " + d.estado + " " + (d.ciudad || "") + " " + d.telefono)
      .toLowerCase().includes(q.toLowerCase())
  );

  if (distribs.length === 0)
    return <Empty big icon="🤝" text="Aún no hay solicitudes. Las que lleguen desde “Quiero ser distribuidor” aparecerán aquí." />;

  return (
    <div className="fadeup">
      <input
        style={{ ...inp(), maxWidth: 320, marginBottom: 14 }}
        placeholder="Buscar por nombre, negocio, estado…"
        value={q}
        onChange={(e) => setQ(e.target.value)}
      />
      <div style={styles.chips}>
        {["Todos", ...DIST_ESTATUS].map((s) => (
          <Chip key={s} active={fil === s} color={s === "Todos" ? "#F04E97" : DIST_COLOR[s]} onClick={() => setFil(s)}>
            {s}
          </Chip>
        ))}
      </div>

      {list.length === 0 ? (
        <Empty icon="🔎" text="No hay solicitudes con ese filtro." />
      ) : (
        <div style={styles.clientGrid}>
          {list.map((d) => {
            const tel = d.telefono.replace(/\D/g, "");
            const wa = "https://wa.me/52" + tel + "?text=" + encodeURIComponent(
              `Hola ${d.nombre}, gracias por tu interés en ser distribuidor de Papitas Saludables. Te comparto nuestros precios preferenciales:`
            );
            const fecha = new Date(d.fecha).toLocaleDateString("es-MX", { day: "2-digit", month: "short", year: "numeric" });
            return (
              <div key={d.folio} className="clientcard">
                <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8, flexWrap: "wrap" }}>
                  <span style={{ fontFamily: "'Baloo 2', cursive", fontSize: 15 }}>{d.folio}</span>
                  <span className="statebad" style={{ background: DIST_COLOR[d.estatus] }}>{d.estatus}</span>
                  <span style={{ marginLeft: "auto", fontSize: 12, color: "#a08a96" }}>{fecha}</span>
                </div>
                <div style={styles.clientName}>{d.nombre}</div>
                {d.negocio && <div style={{ fontSize: 13, color: "#5a4450", fontWeight: 700 }}>{d.negocio}</div>}
                <div style={{ ...styles.clientBody, marginTop: 8 }}>
                  <div>📞 {d.telefono}</div>
                  {d.correo && <div>✉️ {d.correo}</div>}
                  <div>📍 {d.ciudad ? d.ciudad + ", " : ""}{d.estado}</div>
                  {d.tipo && <div style={{ color: "#8a7683" }}>Negocio: {d.tipo}</div>}
                  {d.volumen && <div style={{ color: "#8a7683" }}>Compra estimada: {d.volumen}</div>}
                  {d.mensaje && <div style={{ marginTop: 6, background: "#FBF3E9", borderRadius: 10, padding: "8px 10px", fontSize: 13 }}>📝 {d.mensaje}</div>}
                </div>
                <div style={{ display: "flex", gap: 6, marginTop: 12, flexWrap: "wrap", alignItems: "center" }}>
                  <a className="wabtn" href={wa} target="_blank" rel="noopener noreferrer">WhatsApp</a>
                  {d.correo && <a className="wabtn mail" href={"mailto:" + d.correo}>Correo</a>}
                  <select className="statusel" value={d.estatus} onChange={(e) => onSet(d.folio, e.target.value)}>
                    {DIST_ESTATUS.map((s) => <option key={s}>{s}</option>)}
                  </select>
                  <button className="ghost small danger" onClick={() => { if (confirm("¿Eliminar " + d.folio + "?")) onDelete(d.folio); }}>✕</button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ---------------- utilitarios de UI ----------------
function Panel({ title, children }) {
  return (
    <div style={styles.softPanel}>
      <h3 style={styles.panelTitle}>{title}</h3>
      {children}
    </div>
  );
}
function Empty({ icon, text, big }) {
  return (
    <div style={{ textAlign: "center", padding: big ? "60px 20px" : "26px 16px", color: "#8a7683" }}>
      <div style={{ fontSize: big ? 52 : 34, marginBottom: 8 }}>{icon}</div>
      <p style={{ fontWeight: 700, maxWidth: 340, margin: "0 auto" }}>{text}</p>
    </div>
  );
}

function shade(hex) {
  const n = parseInt(hex.slice(1), 16);
  let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  r = Math.round(r * 0.78); g = Math.round(g * 0.78); b = Math.round(b * 0.78);
  return `rgb(${r},${g},${b})`;
}
function inp(err) {
  return {
    width: "100%", padding: "11px 13px", borderRadius: 14, fontSize: 15,
    border: `2px solid ${err ? "#E8477E" : "#efe2d6"}`, background: "#fff",
    fontFamily: "'Nunito', sans-serif", color: "#4A2C3A", outline: "none", boxSizing: "border-box",
  };
}

